    [STAThread]
    private static void Main(string[] args)
    {
        // Registered before anything else, including the installer helper paths that return before the
        // window exists. They need it most: measured on this machine, `VibeFlow.exe --installer-config-migrate`
        // terminated with an unhandled exception (0xE0434352), which makes the installer report
        // "无法迁移或保护旧版配置，安装未完成" — and with the handlers registered only beside Application.Run,
        // that crash left no report either.
        AppDomain.CurrentDomain.UnhandledException += delegate(object sender, UnhandledExceptionEventArgs e)
        {
            CrashReports.Write("app_domain", e.ExceptionObject as Exception);
        };
        int installerQueryIndex = Array.FindIndex(args, delegate(string arg)
        {
            return arg.Equals(InstallerConfigStartupQueryArgument, StringComparison.OrdinalIgnoreCase);
        });
        if (installerQueryIndex >= 0)
        {
            Environment.ExitCode = installerQueryIndex + 1 < args.Length
                ? QueryConfigStartupForInstaller(args[installerQueryIndex + 1]) : 11;
            return;
        }
        int installerMigrationIndex = Array.FindIndex(args, delegate(string arg)
        {
            return arg.Equals(InstallerConfigMigrationArgument, StringComparison.OrdinalIgnoreCase);
        });
        if (installerMigrationIndex >= 0)
        {
            Environment.ExitCode = installerMigrationIndex + 2 < args.Length
                ? MigrateLegacyUserConfigForInstaller(args[installerMigrationIndex + 1],
                    args[installerMigrationIndex + 2]) : 12;
            return;
        }
        for (int argumentIndex = 0; argumentIndex < args.Length; argumentIndex++)
        {
            string candidate = args[argumentIndex] ?? "";
            if (candidate.StartsWith("--learn-app=", StringComparison.OrdinalIgnoreCase))
                autoLearnProcess = candidate.Substring("--learn-app=".Length).Trim();
            else if (candidate.Equals("--learn-app", StringComparison.OrdinalIgnoreCase) && argumentIndex + 1 < args.Length)
                autoLearnProcess = (args[argumentIndex + 1] ?? "").Trim();
            else if (candidate.StartsWith("--set-app=", StringComparison.OrdinalIgnoreCase))
                autoSetAppProcess = candidate.Substring("--set-app=".Length).Trim();
            else if (candidate.StartsWith("--start-app=", StringComparison.OrdinalIgnoreCase))
                autoStartAppProcess = candidate.Substring("--start-app=".Length).Trim();
            else if (candidate.StartsWith("--learn-and-save=", StringComparison.OrdinalIgnoreCase))
            {
                autoLearnProcess = candidate.Substring("--learn-and-save=".Length).Trim();
                autoLearnThenSave = true;
            }
            else if (candidate.StartsWith("--open-app=", StringComparison.OrdinalIgnoreCase))
                autoOpenAppProcess = candidate.Substring("--open-app=".Length).Trim();
            else if (candidate.StartsWith("--toggle-mode=", StringComparison.OrdinalIgnoreCase))
                autoToggleModeProcess = candidate.Substring("--toggle-mode=".Length).Trim();
            else if (candidate.Equals("--list-installed", StringComparison.OrdinalIgnoreCase))
                autoListInstalled = true;
            else if (candidate.StartsWith("--add-installed=", StringComparison.OrdinalIgnoreCase))
                autoAddInstalledTarget = candidate.Substring("--add-installed=".Length).Trim();
            {
            }
        }
        if (Array.Exists(args, delegate(string arg) { return arg.Equals("--self-test", StringComparison.OrdinalIgnoreCase); }))
        {
            Environment.ExitCode = RunHostSelfTests();
            return;
        }
        TryEnableHighDpi();
        bool background = Array.Exists(args, delegate(string arg) { return arg.Equals("--background", StringComparison.OrdinalIgnoreCase); });
        bool uiResourceTest = Array.Exists(args, delegate(string arg) { return arg.Equals("--ui-resource-test", StringComparison.OrdinalIgnoreCase); });
        bool uiSmoke = uiResourceTest || Array.Exists(args, delegate(string arg) { return arg.Equals("--ui-smoke", StringComparison.OrdinalIgnoreCase); });
        // --ui-theme <light|dark|system>: lets the automated interface check launch the application in each
        // theme. The theme used to be reachable only by editing the configuration, which is why the dark
        // theme shipped unable to start: nothing ever ran it.
        for (int themeIndex = 0; themeIndex < args.Length - 1; themeIndex++)
        {
            if (args[themeIndex].Equals("--ui-theme", StringComparison.OrdinalIgnoreCase))
            {
                themeOverride = (args[themeIndex + 1] ?? "").Trim();
                break;
            }
        }
        // --ui-scale <percent>: lets the automated check launch the application at a chosen interface scale. Like the
        // theme override this is verification only; nothing in normal use passes it.
        for (int scaleIndex = 0; scaleIndex < args.Length - 1; scaleIndex++)
        {
            if (args[scaleIndex].Equals("--ui-scale", StringComparison.OrdinalIgnoreCase))
            {
                int requestedPercent;
                if (int.TryParse(args[scaleIndex + 1], out requestedPercent)) uiScaleOverride = requestedPercent;
                break;
            }
        }
        // --crash-test: throws on the user-interface thread once the window is up, so the crash handler can be
        // verified end to end. Nothing but a verification run passes this, and it is the only way to prove the
        // handler is connected rather than merely present.
        crashTestRequested = Array.Exists(args, delegate(string arg) {
            return arg.Equals("--crash-test", StringComparison.OrdinalIgnoreCase);
        });
        bool createdNew;
        using (var instance = new Mutex(true, uiSmoke ? "Local\\VibeMicUiSmoke" : "Local\\VibeMic", out createdNew))
        {
            if (!createdNew)
            {
                bool replaceExisting = !uiSmoke && ExistingInstanceUsesDifferentPath();
                if (replaceExisting)
                {
                    SignalEvent("Local\\VibeMicExitForUpdate");
                    try { createdNew = instance.WaitOne(12000, false); }
                    catch (AbandonedMutexException) { createdNew = true; }
                }
                if (!createdNew)
                {
                    if (!background && !uiSmoke) SignalEvent("Local\\VibeMicShowWindow");
                    return;
                }
            }
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            // An unhandled exception used to leave nothing behind on the machine except a Windows Error
            // Reporting entry: the dark theme shipped unable to start for months because its crash happened
            // in the host's constructor, where no code of ours was watching. Both paths are recorded now, and
            // the report carries the rendering environment (fonts, screen, scaling) beside the exception —
            // the facts a report from another machine needs and a user cannot be asked to look up.
            //
            // A UI-thread failure is told to the user and the application closes, rather than continuing in a
            // state the code did not expect with a voice session possibly open.
            Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
            Application.ThreadException += delegate(object sender, ThreadExceptionEventArgs e)
            {
                string path = CrashReports.Write("ui_thread", e.Exception);
                try
                {
                    MessageBox.Show(
                        "言灵遇到了一个未处理的错误，已把详情写入：" + Environment.NewLine + path +
                        Environment.NewLine + Environment.NewLine + "请在「设置 · 导出诊断」里一并提供该文件。",
                        "言灵 · 运行错误", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
                catch { }
                Application.Exit();
            };
            Application.Run(new VibeMicForm(background, uiSmoke, uiResourceTest));
        }
    }

    private static void TryEnableHighDpi()
    {
        try
        {
            if (SetProcessDpiAwarenessContext(new IntPtr(-4))) return;
        }
        catch (EntryPointNotFoundException) { }
        catch (DllNotFoundException) { }
        try
        {
            if (SetProcessDpiAwareness(2) == 0) return;
        }
        catch (EntryPointNotFoundException) { }
        catch (DllNotFoundException) { }
        try { SetProcessDPIAware(); }
        catch { }
    }

    private static bool ExistingInstanceUsesDifferentPath()
    {
        try
        {
            string current = Path.GetFullPath(Application.ExecutablePath);
            string[] names = { "VibeFlow", "VibeMic" };
            foreach (string name in names)
            {
                foreach (Process process in Process.GetProcessesByName(name))
                {
                    try
                    {
                        if (process.Id == Process.GetCurrentProcess().Id) continue;
                        string other = Path.GetFullPath(process.MainModule.FileName);
                        if (!other.Equals(current, StringComparison.OrdinalIgnoreCase)) return true;
                    }
                    catch { }
                    finally { process.Dispose(); }
                }
            }
        }
        catch { }
        return false;
    }

    private VibeMicForm(bool launchInBackground, bool smokeMode, bool resourceTestMode)
    {
        backgroundLaunch = launchInBackground;
        uiSmokeMode = smokeMode;
        uiResourceTestMode = resourceTestMode;
        userStateRoot = uiSmokeMode ? Path.Combine(root, "tmp", "ui-smoke") : GetUserStateRoot();
        Directory.CreateDirectory(userStateRoot);
        recordingPriorityCommitGate = new RecordingPriorityCommitGate(ProjectRecordingHasPriority);
        focusTargetStore = new FocusTargetStore(userStateRoot);
        linkBaselineStore = new LinkBaselineStore(userStateRoot);
        favoriteAppStore = new FavoriteAppStore(userStateRoot);
        snippetStore = new SnippetStore(userStateRoot);
        // Publish read-only snippet lookups for the static action-label helpers. They are pinned by the
        // source gates, so they cannot take Host instance state; see SnippetNaming for the reasoning.
        SnippetNaming.ResolveName = delegate(string id)
        {
            return SnippetStore.Describe(snippetStore.Load(), SnippetStore.ActionFor(id));
        };
        SnippetNaming.ResolveAll = delegate { return snippetStore.Load().snippets; };
        focusAutomationBackend = new WindowsUiaFocusAutomationBackend(recordingPriorityCommitGate);
        focusTargetService = new FocusTargetService(focusAutomationBackend, IsVoiceKeyHeld, HostLog,
            recordingPriorityCommitGate);
        focusTargetDocument = LoadFocusTargetDocument();
        string migratedConfigSource = uiSmokeMode ? "" : MigrateLegacyUserConfig(root, userStateRoot);
        sessionDir = Path.Combine(userStateRoot, "remote-voice-session");
        configPath = Path.Combine(userStateRoot, "vibe-mic-config.json");
        eventsPath = Path.Combine(sessionDir, "remote-voice-events.jsonl");
        brandLogoPath = Path.Combine(root, "vibe-flow-logo.png");
        hostLogPath = Path.Combine(sessionDir, "vibe-flow-host.log");
        Directory.CreateDirectory(sessionDir);
        // A fresh install used to start with an empty layer table, which made the entire three-layer
        // gesture surface invisible until the user authored it by hand. The recommended table is
        // written once, and only when no table exists at all: an existing table — including one the
        // user deliberately emptied — is never touched. This runs after hostLogPath exists, because
        // the seeding line is the only record that a machine received these defaults.
        EnsureGestureLayerDefaults();
        // Whether the previous session died. A crash that leaves no trace in the next session's log is a
        // crash nobody looks for, which is how a theme that could not start survived unnoticed.
        ReportPreviousCrashes();
        config = LoadConfig();
        if (uiSmokeMode)
        {
            config = VibeMicConfig.Default();
            config.setupCompleted = true;
            config.resumeSetupAfterRestart = false;
            config.launchAtStartup = false;
            config.startBridgeOnLaunch = false;
            config.minimizeToTray = false;
            File.WriteAllText(configPath, new JavaScriptSerializer().Serialize(config), Encoding.UTF8);
        }
        // An explicitly requested theme, so the interface can be verified in every theme without editing a
        // configuration file first. Verification only: nothing passes this flag in normal use, and an
        // unknown value is ignored rather than written anywhere.
        if (!string.IsNullOrWhiteSpace(themeOverride))
        {
            string requested = themeOverride.Trim().ToLowerInvariant();
            if (requested == "light" || requested == "dark" || requested == "system")
                config.theme = requested;
        }
        // The user's interface scale, on top of the display's own. It is applied once here, before the shell is built,
        // because the window and its layout are sized when they load: a change from the settings page takes effect on
        // the next start, which is what its note says.
        UiDisplayScale.UserScale = ClampUiScaleFactor(uiScaleOverride > 0 ? uiScaleOverride : config.uiScalePercent);
        HostLog("UI SCALE override=" + uiScaleOverride + " configured=" + config.uiScalePercent +
            " factor=" + UiDisplayScale.UserScale.ToString("0.00"));
        InitializeProjectSpaces();
        InitializeBrowserRemoteLite();
        InitializeCaptureAsk();
        ApplyThemePalette();
        if (!uiSmokeMode) ClearPendingCustomButtonCapture("startup");
        // The bridge must never start from a stale packaged mapping file. Rebuild
        // it from the migrated user config before any background service starts.
        if (!uiSmokeMode && !configurationWritesBlocked) SyncKeyboardBridgeConfig();
        if (!uiSmokeMode && !configurationWritesBlocked) ReconcileLaunchAtStartupRegistration();
        if (!uiSmokeMode) ReleaseVoiceHotkey();
        RotateLogFile(Path.Combine(sessionDir, "vibe-mic-runtime.log"), 4 * 1024 * 1024);
        RotateLogFile(hostLogPath, 2 * 1024 * 1024);
        RotateLogFile(Path.Combine(root, "input-bridge-log.txt"), 4 * 1024 * 1024);
        if (!uiSmokeMode)
        {
            audioDuckingLease = new WindowsAudioDuckingLease(
                Path.Combine(sessionDir, "windows-audio-ducking-lease.json"), HostLog);
            InitializeFeedbackSounds();
        }
        string existingRuntimeLog = Path.Combine(sessionDir, "vibe-mic-runtime.log");
        runtimeFeedbackPosition = File.Exists(existingRuntimeLog) ? new FileInfo(existingRuntimeLog).Length : 0;
        string existingInputLog = Path.Combine(root, "input-bridge-log.txt");
        inputFeedbackPosition = File.Exists(existingInputLog) ? new FileInfo(existingInputLog).Length : 0;

        AutoScaleDimensions = new SizeF(96f, 96f);
        AutoScaleMode = AutoScaleMode.Dpi;
        Text = DisplayProductName + " · V" + ProductRelease;
        Width = 1280;
        Height = 840;
        MinimumSize = new Size(880, 500);
        StartPosition = FormStartPosition.CenterScreen;
        if (backgroundLaunch)
        {
            StartPosition = FormStartPosition.Manual;
            Location = new Point(-32000, -32000);
            ShowInTaskbar = false;
        }
        BackColor = pageBackground;
        Font = UiFonts.Text(10f);
        Icon = CreateAppIcon();
        DoubleBuffered = true;

        BuildShell();
        EnsureLiveHud();
        ShowPage(PageHome);
        if (configurationWritesBlocked)
        {
            latestActionResult = ActionResult.Create("加载配置", "本地配置", ActionState.Error,
                "检测到更新版本的配置，已进入只读保护",
                "当前程序支持 schema " + ConfigSchemaVersion + "，配置为 schema " +
                    unsupportedConfigSchemaVersion + "；未启动按键或语音服务，也未改写配置",
                "请使用创建该配置的新版 Vibe Flow；如需降级，请先备份并移开较新配置",
                "CONFIG-SCHEMA-NEWER");
            ShowActionToast(latestActionResult);
        }
        if (!uiSmokeMode) SetupTray();
        HostLog("HOST START mode=" + (backgroundLaunch ? "background" : "interactive") +
            " provider=" + NormalizeProviderKey(config.inputMethod) + " startup=" + config.launchAtStartup +
            " ui_smoke=" + uiSmokeMode);
        if (!string.IsNullOrWhiteSpace(migratedConfigSource))
            HostLog("CONFIG MIGRATED source=legacy_install destination=user_state source_file=" +
                SafeLogValue(migratedConfigSource));
        if (!uiSmokeMode)
        {
            showWindowEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicShowWindow");
            exitApplicationEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicExitForUpdate");
            voiceWakeRequestEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicVoiceWakeRequested");
            providerHotkeyTapEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicProviderHotkeyTapRequested");
            providerHotkeyDownEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicProviderHotkeyDownRequested");
            providerHotkeyUpEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicProviderHotkeyUpRequested");
            inputTargetMissingEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicInputTargetMissing");
            focusTargetLockedEvent = new EventWaitHandle(false, EventResetMode.ManualReset, "Local\\VibeMicFocusTargetLocked");
            focusTargetLockedEvent.Reset();
            recordingStartCueEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicRecordingStartCue");
            recordingStopCueEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\VibeMicRecordingStopCue");
            ThreadPool.QueueUserWorkItem(delegate
            {
                WaitHandle[] handles = { showWindowEvent, exitApplicationEvent, voiceWakeRequestEvent,
                    providerHotkeyTapEvent, providerHotkeyDownEvent, providerHotkeyUpEvent, inputTargetMissingEvent };
                while (!applicationExiting && !IsDisposed)
                {
                    try
                    {
                        int signal = WaitHandle.WaitAny(handles);
                        if (IsDisposed || applicationExiting) return;
                        if (signal == 0) BeginInvoke(new Action(ShowMainWindow));
                        else if (signal == 1) BeginInvoke(new Action(delegate { config.minimizeToTray = false; Close(); }));
                        else if (signal == 2)
                        {
                            // The physical key edge is already held by the
                            // time this event arrives.  Observe the current
                            // editable target synchronously before the UI
                            // thread paints any feedback, so provider startup
                            // cannot race a stale or lost focus.
                            bool focusPrepared = PrepareVoiceFocusForWake();
                            BeginInvoke(new Action(delegate
                            {
                                HandleVoiceWakeRequest(focusPrepared);
                            }));
                        }
                        else if (signal == 3) HandleProviderHotkeyTapRequest();
                        else if (signal == 4 || signal == 5) HandleProviderHotkeyHoldRequest(signal == 4);
                        else if (signal == 6) BeginInvoke(new Action(HandleMissingInputTarget));
                    }
                    catch (Exception ex)
                    {
                        // A transient UI Automation/BeginInvoke failure must
                        // not permanently kill the named-event listener. The
                        // next event remains actionable after a short bounded
                        // backoff, while shutdown still exits through the
                        // applicationExiting flag above.
                        HostLog("VOICE EVENT LISTENER recoverable_error=" +
                            SafeLogValue(ex.GetType().Name));
                        if (!applicationExiting) Thread.Sleep(100);
                    }
                }
            });
            StartRecordingCueWorker();
        }

        if (!uiSmokeMode)
        {
            activityTimer = new System.Windows.Forms.Timer();
            activityTimer.Interval = 500;
            activityTimer.Tick += delegate { PollActivity(); };
            activityTimer.Start();
        }

        visualTimer = new System.Windows.Forms.Timer();
        visualTimer.Interval = 500;
        visualTimer.Tick += delegate
        {
            if (!Visible || WindowState == FormWindowState.Minimized)
            {
                if (visualTimer.Interval != 500) visualTimer.Interval = 500;
                return;
            }
            if (currentVisualState == "stopped")
            {
                if (visualTimer.Interval != 250) visualTimer.Interval = 250;
                return;
            }
            // Feedback surfaces are invalidated by real state transitions.  A
            // periodic repaint is intentionally avoided so recording never
            // causes a focus-visible refresh loop.
            if (visualTimer.Interval != 500) visualTimer.Interval = 500;
        };
        visualTimer.Start();
        if (!uiSmokeMode)
        {
            SystemEvents.PowerModeChanged += OnPowerModeChanged;
            SystemEvents.SessionSwitch += OnSessionSwitch;
            SystemEvents.UserPreferenceChanged += OnUserPreferenceChanged;
            if (config.autoCheckUpdates) ScheduleAutomaticUpdateCheck();
        }
        if (uiResourceTestMode) Shown += delegate { BeginInvoke(new Action(RunPageResourceTest)); };
    }

    // Asserts that a surface is laid out at the display scaling, and that nothing inside it overlaps.
    //
    // The Context Deck and Capture & Ask are opened only from the tray menu, so they have no route through the
    // application's own interface: reaching them from outside would mean driving the user's own tray icon. The
    // rule the external geometry check applies to the pages and the dialogs is applied here instead, which also
    // means the release chain checks these two surfaces on every build rather than when someone measures by
    // hand. Measured before asserting: a freshly shown Context Deck is 1640x1392 where 820x696 times this
    // display's scaling is exactly that, so the expectation is evidence and not arithmetic.
    internal static void AssertSurfaceGeometry(Form surface, Size designSize, string name)
    {
        if (surface == null) throw new InvalidOperationException(name + " was not constructed");
        float scale = UiDisplayScale.ForControl(surface);
        int expectedWidth = (int)Math.Round(designSize.Width * scale);
        int expectedHeight = (int)Math.Round(designSize.Height * scale);
        if (Math.Abs(surface.Width - expectedWidth) > 2 || Math.Abs(surface.Height - expectedHeight) > 2)
        {
            throw new InvalidOperationException(name + " is " + surface.Width + "x" + surface.Height +
                " where its design size at this display scaling is " + expectedWidth + "x" + expectedHeight);
        }
        string overlap = FindSiblingOverlapText(surface);
        if (overlap.Length > 0)
            throw new InvalidOperationException(name + " has overlapping controls: " + overlap);
    }

    // Two sibling controls overlapping by more than a couple of pixels. The threshold matches the external
    // check: touching edges are not an overlap, and a one-pixel rounding difference is not a defect.
    private static string FindSiblingOverlapText(Control root)
    {
        foreach (Control container in AllDescendants(root))
        {
            var children = new List<Control>();
            foreach (Control child in container.Controls)
            {
                if (!child.Visible || child.Width <= 0 || child.Height <= 0) continue;
                children.Add(child);
            }
            for (int first = 0; first < children.Count; first++)
            {
                for (int second = first + 1; second < children.Count; second++)
                {
                    Rectangle a = children[first].Bounds;
                    Rectangle b = children[second].Bounds;
                    int overlapX = Math.Min(a.Right, b.Right) - Math.Max(a.Left, b.Left);
                    int overlapY = Math.Min(a.Bottom, b.Bottom) - Math.Max(a.Top, b.Top);
                    if (overlapX > 2 && overlapY > 2)
                    {
                        return TabOrderControlName(children[first]) + " x " + TabOrderControlName(children[second]) +
                            " " + overlapX + "x" + overlapY;
                    }
                }
            }
        }
        return "";
    }

    private static string TabOrderControlName(Control control)
    {
        string label = control.Text;
        if (string.IsNullOrWhiteSpace(label)) label = control.Name;
        if (string.IsNullOrWhiteSpace(label)) label = control.GetType().Name;
        return label.Length > 24 ? label.Substring(0, 24) : label;
    }

    // Checks a form's scaling and reports it, before and after it is shown.
    //
    // Two families, and the measurement is what separates them. A form carrying a design baseline
    // (AutoScaleDimensions) is scaled by Windows Forms, which scales the *client area* and leaves the frame
    // alone — so its window comes out one frame smaller than the design window times the scaling. A form without
    // one is scaled by UiDisplayScale, which scales the window itself. Both were measured on this machine: with
    // the frame accounted for, every wired form matches its design size times the display scaling.
    private void CheckSurfaceScaling(string name, Form surface, Size designSize)
    {
        if (surface == null) { return; }
        try
        {
            Size constructed = surface.Size;
            Size baseline = surface.AutoScaleDimensions.ToSize();
            surface.Show();
            Application.DoEvents();
            float scale = UiDisplayScale.ForControl(surface);
            // Which family this form belongs to is a measured fact, not a property: a form that is already larger
            // than its design size at the end of its constructor has been scaled by Windows Forms, which scales
            // the client area and leaves the frame alone; a form still at its design size there is scaled by
            // UiDisplayScale, which scales the window. The autoscale baseline does not distinguish them — the
            // Context Deck carries one and is still scaled by this code, which is why its client area is not the
            // value to compare.
            bool autoscaledByWindowsForms = constructed.Width > designSize.Width + 4 ||
                constructed.Height > designSize.Height + 4;
            Size frame = new Size(surface.Width - surface.ClientSize.Width,
                surface.Height - surface.ClientSize.Height);
            Size expectedClient = new Size(
                (int)Math.Round((designSize.Width - frame.Width) * scale),
                (int)Math.Round((designSize.Height - frame.Height) * scale));
            Size expectedWindow = new Size((int)Math.Round(designSize.Width * scale),
                (int)Math.Round(designSize.Height * scale));
            Size actual = autoscaledByWindowsForms ? surface.ClientSize : surface.Size;
            Size expected = autoscaledByWindowsForms ? expectedClient : expectedWindow;
            bool matches = Math.Abs(actual.Width - expected.Width) <= 2 && Math.Abs(actual.Height - expected.Height) <= 2;
            HostLog("UI DISPLAYSCALE " + name + "=" + (matches ? "ok" : "MISMATCH") +
                " constructed=" + constructed.Width + "x" + constructed.Height +
                " shown=" + surface.Width + "x" + surface.Height +
                " client=" + surface.ClientSize.Width + "x" + surface.ClientSize.Height +
                " frame=" + frame.Width + "x" + frame.Height +
                " compared=" + (autoscaledByWindowsForms ? "client" : "window") +
                " actual=" + actual.Width + "x" + actual.Height +
                " expected=" + expected.Width + "x" + expected.Height +
                " scale=" + scale.ToString("0.00"));
            if (!matches)
            {
                throw new InvalidOperationException(name + " is " + actual.Width + "x" + actual.Height +
                    " where its design size at this display scaling is " + expected.Width + "x" + expected.Height);
            }
        }
        finally
        {
            try { surface.Hide(); } catch { }
            try { surface.Dispose(); } catch { }
            Application.DoEvents();
        }
    }

    // The picker's dialog needs a list; an empty one is enough to construct it for measurement.
    private static List<InstalledAppChoice> BuildInstalledAppChoicesForDiagnostic()
    {
        return new List<InstalledAppChoice>();
    }

    // The diagnostics report is built and checked in a smoke run, using the same builder the export writes. The
    // save dialog cannot be driven from a test, so this is the part that can be: it is what a user's report will
    // contain. The crash section is conditional — a machine with no crashes should say zero rather than show an
    // empty block — so only its presence is required here, and the crash writer's own self-test covers the
    // content of a report.
    private void CheckDiagnosticsReport()
    {
        string report = BuildDiagnosticsReport();
        if (string.IsNullOrWhiteSpace(report))
            throw new InvalidOperationException("The diagnostics report is empty");
        string[] required = {
            "Technical diagnostics", "Generated: ", "Windows: ", "App: ", "Capture running: ",
            "UI rendering: ", "Display: ", "Crashes recorded: ", "Mappings: "
        };
        foreach (string fragment in required)
        {
            if (report.IndexOf(fragment, StringComparison.Ordinal) < 0)
                throw new InvalidOperationException("The diagnostics report is missing: " + fragment);
        }
        int crashLine = report.IndexOf("Crashes recorded: ", StringComparison.Ordinal);
        string countText = report.Substring(crashLine + "Crashes recorded: ".Length);
        countText = countText.Substring(0, countText.IndexOf('\n') < 0 ? countText.Length : countText.IndexOf('\n')).Trim();
        int parsed;
        if (!int.TryParse(countText.Split(' ')[0], out parsed))
            throw new InvalidOperationException("The diagnostics report does not state a crash count: " + countText);
        // When reports exist, the newest one has to be in the export — that is the whole point of including it,
        // and this is the only place the inclusion can be checked without driving the save dialog.
        if (parsed > 0 && report.IndexOf("Newest crash report", StringComparison.Ordinal) < 0)
            throw new InvalidOperationException("The diagnostics report states " + parsed +
                " crashes but does not include the newest one");
        HostLog("UI DIAGNOSTICS report=ok length=" + report.Length + " crashes=" + parsed +
            " includesNewest=" + (report.IndexOf("Newest crash report", StringComparison.Ordinal) >= 0));
    }

    // Measures the Capture & Ask surface, the one interface that has no route through the application's own
    // pages: it opens from the tray menu only. The host has the service it needs, so this instance method can
    // do what the static self-test cannot. The assertion is the same one the Context Deck uses — design size
    // times the display scaling, and no overlapping siblings — and a failure is loud, because a surface that
    // renders wrongly should stop the run rather than be recorded as fine.
    private void MeasureTraySurfaceGeometry()
    {
        // All five wired forms are compared here, because "the window is exactly twice its design size" cannot
        // tell one scaling from two — measured, Browser Remote Lite's design size times two is the same number
        // as the working area clamp. The size at construction and the size after being shown can tell them
        // apart, together with the autoscale baseline Windows Forms records.
        CheckSurfaceScaling("ContextDeck", new ContextDeckForm(), new Size(820, 696));
        // LiveHudForm's design size is 400x160 (its constructor), not the 200x80 this diagnostic first assumed:
        // the wrong baseline made a correct form look like it had been scaled four times.
        CheckSurfaceScaling("LiveHud", new LiveHudForm(), new Size(400, 160));
        try
        {
            CheckSurfaceScaling("AppPicker", new AppPickerDialog(BuildInstalledAppChoicesForDiagnostic()),
                new Size(580, 660));
        }
        catch (Exception ex)
        {
            HostLog("UI DISPLAYSCALE AppPicker=unavailable error=" + SafeLogValue(ex.Message));
        }
        try
        {
            // The callbacks are only invoked on user interaction, and the constructor fills in defaults for the
            // ones it needs, so nulls are enough to construct it for measurement.
            CheckSurfaceScaling("BrowserRemoteLite",
                new BrowserRemoteLiteForm(null, null, null, null, null, null, false), new Size(840, 720));
        }
        catch (Exception ex)
        {
            HostLog("UI DISPLAYSCALE BrowserRemoteLite=unavailable error=" + SafeLogValue(ex.Message));
        }

        CaptureAskForm probe = null;
        try
        {
            // Constructed here rather than through ShowCaptureAsk, and measured at each step: the question is
            // where the size comes from, and a single number at the end cannot answer that. Windows Forms
            // autoscales a form whose AutoScaleMode is Dpi, and UiDisplayScale scales it again at load, so the
            // two can act on the same form — measured, this one ended up filling the working area, which is what
            // a size larger than the area looks like after clamping.
            probe = new CaptureAskForm(this, captureAskService, captureAskBackend,
                new List<FocusTargetDescriptor>(), "", delegate { return false; }, delegate { }, delegate { });
            HostLog("UI TRAY SURFACE probe constructed=" + probe.Width + "x" + probe.Height +
                " autoscaleDimensions=" + probe.AutoScaleDimensions.Width + "x" + probe.AutoScaleDimensions.Height +
                " autoscaleMode=" + probe.AutoScaleMode +
                " minimum=" + probe.MinimumSize.Width + "x" + probe.MinimumSize.Height);
            probe.Show();
            Application.DoEvents();
            float probeScale = UiDisplayScale.ForControl(probe);
            // Same measured rule as the other forms: this one is already larger than its design size when its
            // constructor returns, so Windows Forms scaled it and its *client area* is what has to match — its
            // window is one unscaled frame smaller than the design window times the scaling.
            Size probeFrame = new Size(probe.Width - probe.ClientSize.Width,
                probe.Height - probe.ClientSize.Height);
            int expectedWidth = (int)Math.Round((780 - probeFrame.Width) * probeScale);
            int expectedHeight = (int)Math.Round((700 - probeFrame.Height) * probeScale);
            bool matches = Math.Abs(probe.ClientSize.Width - expectedWidth) <= 2 &&
                Math.Abs(probe.ClientSize.Height - expectedHeight) <= 2;
            HostLog("UI TRAY SURFACE captureAsk=" + (matches ? "ok" : "MISMATCH") +
                " shown=" + probe.Width + "x" + probe.Height +
                " expected=" + expectedWidth + "x" + expectedHeight +
                " difference=" + (probe.Width - expectedWidth) + "x" + (probe.Height - expectedHeight) +
                " client=" + probe.ClientSize.Width + "x" + probe.ClientSize.Height +
                " scale=" + probeScale.ToString("0.00") +
                " workarea=" + Screen.FromControl(probe).WorkingArea.Width + "x" +
                Screen.FromControl(probe).WorkingArea.Height);
            if (!matches)
            {
                throw new InvalidOperationException("Capture & Ask is " + probe.ClientSize.Width + "x" +
                    probe.ClientSize.Height + " where its design client size at this display scaling is " +
                    expectedWidth + "x" + expectedHeight);
            }
        }
        catch (Exception ex)
        {
            HostLog("UI TRAY SURFACE captureAsk failed error=" + SafeLogValue(ex.Message));
            throw;
        }
        finally
        {
            try { if (probe != null) probe.Close(); } catch { }
            Application.DoEvents();
        }
    }

    // Walks every page's keyboard order and logs it, so the order is measured rather than assumed.
    //
    // This exists because no external instrument on this machine can read it: UI Automation reports every
    // control of a Windows Forms application as ControlType.Pane here (a minimal application built the same
    // way does too), AttachThreadInput is refused, and SendKeys needs the window in front, which the harness
    // cannot take. SelectNextControl needs none of that — it is a query against the control tree — and the
    // walk carries its own control case: the settings page holds two read-only rows that are check boxes
    // with TabStop=false, so a walk that visits them is measuring something other than the tab order.
    private void LogTabOrderDiagnostic()
    {
        // Logged once: OnShown can run more than once, and a duplicated measurement reads like a second
        // page's worth of data.
        if (tabOrderLogged) return;
        tabOrderLogged = true;
        for (int page = 0; page < UiDesignTokens.PageCount; page++)
        {
            ShowPage(page);
            // Visits are tracked by control identity, not by name. The first version keyed on the label and
            // therefore stopped at the first repeated one: the 自检 page holds a column of buttons that all
            // read "打开应用并学习", so that walk reported 1 reachable control where there are many — a
            // plausible number that measured something other than the tab order.
            var visited = new List<Control>();
            var visitedNames = new List<string>();
            var skipped = new List<string>();
            Control current = this;
            for (int step = 0; step < 500; step++)
            {
                // Wrapping is what makes the count meaningful: without it a walk that reaches the last
                // control returns false and stops, so the total says nothing about whether more controls
                // exist. With wrapping the walk continues through the whole order and ends when it returns to
                // a control it has already seen, which is the number of controls Tab can actually reach.
                if (!SelectNextControl(current, true, true, true, true)) break;
                current = ActiveControl;
                if (current == null) break;
                if (visited.Contains(current)) break;
                visited.Add(current);
                visitedNames.Add(ControlNameForTabOrder(current));
            }
            // Every operable control that is deliberately out of the tab order, to prove the walk's reach.
            foreach (Control control in AllDescendants(this))
            {
                if (control.TabStop || !IsOperableControl(control)) continue;
                skipped.Add(ControlNameForTabOrder(control));
            }
            HostLog("UI TABORDER page=" + page + " stops=" + visited.Count +
                " tabbableInTree=" + CountTabbableInTree(this) +
                " skippedNonTabStop=" + skipped.Count +
                " visitedNonTabStop=" + CountVisitedNotTabbable(visitedNames) +
                " first=" + (visitedNames.Count > 0 ? visitedNames[0] : "-") +
                " last=" + (visitedNames.Count > 0 ? visitedNames[visitedNames.Count - 1] : "-") +
                " order=" + string.Join(" > ", visitedNames.ToArray()));
            // Assertions, because a walk that reports nothing looks the same as a walk that found nothing wrong.
            // The middle one is the negative control: reaching a control that refuses focus means the walk is
            // measuring something other than the tab order. The last is the regression bound for the bug this
            // walk had: keyed on the control's label, it stopped at the first repeated label and reported 1
            // reachable control on a page holding 34.
            if (visited.Count <= 0)
                throw new InvalidOperationException("Keyboard order: page " + page + " reaches no control at all");
            if (CountVisitedNotTabbable(visitedNames) != 0)
                throw new InvalidOperationException("Keyboard order: page " + page +
                    " reaches a control that is not a tab stop");
            int tabbable = CountTabbableInTree(this);
            if (tabbable >= 4 && visited.Count < tabbable - 2)
                throw new InvalidOperationException("Keyboard order: page " + page + " reaches " + visited.Count +
                    " of " + tabbable + " tab stops");
        }
        ShowPage(PageHome);
    }

    // How many controls in the tree are marked as tab stops. Logged beside the walk because the two can
    // disagree, and a disagreement is information: the walk only reaches what can actually take focus, while
    // this counts what asked to be in the order.
    private int CountTabbableInTree(Control root)
    {
        int count = 0;
        foreach (Control control in AllDescendants(root))
        {
            if (control.TabStop && IsOperableControl(control)) count++;
        }
        return count;
    }

    // Whether a control is something a mouse can operate, so something the keyboard should reach.
    private static bool IsOperableControl(Control control)
    {
        return control is Button || control is TextBoxBase || control is ComboBox ||
            control is CheckBox || control is RadioButton || control is ListControl ||
            control is NumericUpDown || control is TrackBar;
    }

    // The names of visited controls that are not supposed to accept focus: any of these means the walk is
    // reporting something other than the tab order.
    private static int CountVisitedNotTabbable(List<string> visited)
    {
        int count = 0;
        foreach (string name in visited) if (name.StartsWith("!", StringComparison.Ordinal)) count++;
        return count;
    }

    private static string ControlNameForTabOrder(Control control)
    {
        string label = control.Text;
        if (string.IsNullOrWhiteSpace(label)) label = control.Name;
        if (string.IsNullOrWhiteSpace(label)) label = control.GetType().Name;
        if (label.Length > 24) label = label.Substring(0, 24);
        // The marker makes a visit to a deliberately unreachable control visible in the log rather than
        // something that has to be inferred.
        return (control.TabStop ? "" : "!") + label;
    }

    private static IEnumerable<Control> AllDescendants(Control root)
    {
        foreach (Control child in root.Controls)
        {
            yield return child;
            foreach (Control nested in AllDescendants(child)) yield return nested;
        }
    }

    // Says in this session's log whether the previous one ended in a recorded crash, and what it was.
    private void ReportPreviousCrashes()
    {
        var reports = CrashReports.ExistingReports();
        if (reports.Count == 0) return;
        HostLog("CRASH PREVIOUS count=" + reports.Count + " newest=" + Path.GetFileName(reports[0]));
        foreach (string line in CrashReports.Summarize(reports[0], 8).Split('\n'))
        {
            string trimmed = line.Trim();
            if (trimmed.Length == 0) continue;
            HostLog("CRASH PREVIOUS " + SafeLogValue(trimmed));
        }
    }

    // The crash writer, exercised on a synthetic exception: a crash reporter that has never been run is a
    // crash reporter that does not work, and this is the only way to check the report's contents without
    // actually crashing.
    private static void RunCrashReportSelfTests()
    {
        string directory = Path.Combine(Path.GetTempPath(), "vibe-crash-selftest-" + Guid.NewGuid().ToString("N"));
        try
        {
            string path = CrashReports.Write(directory, "self_test",
                new InvalidOperationException("outer failure", new ApplicationException("inner cause")));
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
                throw new InvalidOperationException("The crash writer did not produce a report");
            string text = File.ReadAllText(path, Encoding.UTF8);
            string[] required = {
                "Exception: System.InvalidOperationException", "Message: outer failure", "Inner:",
                "Exception: System.ApplicationException", "Message: inner cause",
                "Source: self_test", "Interface: ", "Display: ", "Stack:"
            };
            foreach (string fragment in required)
            {
                if (text.IndexOf(fragment, StringComparison.Ordinal) < 0)
                    throw new InvalidOperationException("The crash report is missing: " + fragment);
            }
            // Pruning: an unbounded diagnostic trail grows without anyone noticing.
            for (int index = 0; index < CrashReports.KeepNewest + 3; index++)
                CrashReports.Write(directory, "self_test_" + index, new InvalidOperationException("filler " + index));
            int remaining = CrashReports.ExistingReports(directory).Count;
            if (remaining > CrashReports.KeepNewest)
                throw new InvalidOperationException("Crash reports are not pruned: " + remaining);
            // A null exception must still produce a readable report rather than throwing inside the handler.
            string emptyPath = CrashReports.Write(directory, "self_test_null", null);
            if (string.IsNullOrWhiteSpace(emptyPath) ||
                File.ReadAllText(emptyPath, Encoding.UTF8).IndexOf("(none supplied)", StringComparison.Ordinal) < 0)
                throw new InvalidOperationException("The crash writer cannot describe a missing exception");
        }
        finally
        {
            try { if (Directory.Exists(directory)) Directory.Delete(directory, true); } catch { }
        }
    }

    private void ClampWindowToWorkingArea()
    {
        Rectangle work = Screen.FromControl(this).WorkingArea;
        // The window is laid out for 1280x840 at 96 dpi, and its size has to follow the display scaling
        // the way the content does. It did not: measured with the app's own diagnostic, the window
        // reported 1280x840 at 100% and again at 150%, so at 150% the same physical window had to hold
        // content that is 1.5x bigger — the pages no longer fit and the rows inside them collided
        // (measured with scripts/check-ui-geometry.ps1). Scaling the window here, before the work-area
        // clamp, keeps the interface the same apparent size at every setting.
        float scale = DesignScale();
        if (scale > 1.01f)
        {
            Width = (int)Math.Round(1280 * scale);
            Height = (int)Math.Round(840 * scale);
            // The minimum size is a design measurement like any other, and it was left unscaled: at 200% the
            // window could still be dragged down to 880x500 device pixels, which is 440x250 logical — below
            // anything the layout was built for, with the sidebar alone taking more than half of it. Fitting
            // to a smaller work area still lowers this, so a small screen is not locked out.
            MinimumSize = new Size(ScaledDesign(880), ScaledDesign(500));
            // The shell (sidebar, footer, tray menu) is built in the constructor, before this, and its
            // containers did not follow the scaling either: measured at 150%, the sidebar stayed 232 px
            // wide while the pages grew by half.
            ScaleLayoutTree(this, scale);
        }
        VibeWindowLayout.FitToWorkingArea(this, work, 32);
    }

    // The display scaling this window is rendered at, relative to the 96 dpi the layout was designed at.
    // 100% to 150%, with anything unset or out of range meaning 100%.
    private static float ClampUiScaleFactor(int percent)
    {
        if (percent <= 0) return 1f;
        int clamped = Math.Max(100, Math.Min(150, percent));
        return clamped / 100f;
    }

    private float DesignScale()
    {
        try
        {
            uint dpi = CurrentWindowDpi();
                if (dpi >= 48 && dpi <= 480) return dpi / 96f * UiDisplayScale.UserScale;
        }
        catch { }
        return 1f;
    }

    // A design measurement in device pixels at the current scaling.
    private int ScaledDesign(int designPixels)
    {
        float scale = DesignScale();
        return scale <= 1.01f ? designPixels : (int)Math.Round(designPixels * scale);
    }

    // Scales a freshly built page's geometry by the display scaling. The algorithm lives in
    // UiDisplayScale so the pages, the wizard and the dialogs cannot drift apart; these wrappers keep the
    // call sites and the gates that pin them readable.
    private static void ScaleLayoutTree(Control parent, float scale)
    {
        UiDisplayScale.Tree(parent, scale);
    }

    // Scales one control's own bounds by the display scaling, honouring its dock and auto-size state.
    private static void ScaleControlBounds(Control control, float scale)
    {
        UiDisplayScale.Bounds(control, scale);
    }

    // Scales a surface whose content is built piecemeal and refilled later — the setup wizard's step pane
    // is cleared and rebuilt on every step change, and its builder returns early from many branches, so
    // scaling "once at the end" never ran: at 200% the pane was laid out at 96 dpi with doubled fonts,
    // which truncated the step labels and squashed the subtitle.
    private void ScaleControlsAddedLater(Control root)
    {
        UiDisplayScale.AddedLater(root, DesignScale());
    }

    private uint CurrentWindowDpi()
    {
        try { return GetDpiForWindow(Handle); }
        catch
        {
            using (Graphics graphics = CreateGraphics()) return (uint)Math.Round(graphics.DpiX);
        }
    }

    // The screen facts a layout report needs: the display's resolution, the scaling Windows applies,
    // the work area the window may use, and the window's own size once it has been clamped. Logged
    // and exported, so "the interface is squeezed on my machine" becomes a measurement rather than a
    // description. Never throws: this is a diagnostic on the startup path.
    internal string DescribeScreenGeometry()
    {
        try
        {
            Rectangle bounds = Screen.PrimaryScreen == null ? Rectangle.Empty : Screen.PrimaryScreen.Bounds;
            Rectangle work = Screen.PrimaryScreen == null ? Rectangle.Empty : Screen.PrimaryScreen.WorkingArea;
            uint dpi = CurrentWindowDpi();
            return "screen=" + bounds.Width + "x" + bounds.Height +
                " workarea=" + work.Width + "x" + work.Height +
                " dpi=" + dpi + " scale=" + Math.Round(dpi / 96.0, 2).ToString("0.00") +
                " monitors=" + Screen.AllScreens.Length +
                " window=" + Width + "x" + Height +
                // How small the window may be dragged: a design measurement that has to follow the scaling
                // too, or a scaled interface can be shrunk to a fraction of the size it was built for.
                " minimum=" + MinimumSize.Width + "x" + MinimumSize.Height +
                // Which containers follow the scaling and which do not: the two are easy to confuse when
                // only the window size is visible, and this is the line a report carries.
                " sidebar=" + (sidebarPanel == null ? "?" : sidebarPanel.Width + "x" + sidebarPanel.Height) +
                " content=" + (content == null ? "?" : content.ClientSize.Width + "x" + content.ClientSize.Height) +
                " scroll=" + (content == null ? "?" :
                    content.AutoScrollMinSize.Width + "x" + content.AutoScrollMinSize.Height);
        }
        catch (Exception ex)
        {
            return "screen=unavailable error=" + ex.GetType().Name;
        }
    }

    private void OnPowerModeChanged(object sender, PowerModeChangedEventArgs e)
    {
        if (e.Mode == PowerModes.Resume) ScheduleSystemRecovery("power_resume");
    }

    private void OnSessionSwitch(object sender, SessionSwitchEventArgs e)
    {
        if (e.Reason == SessionSwitchReason.SessionUnlock ||
            e.Reason == SessionSwitchReason.ConsoleConnect ||
            e.Reason == SessionSwitchReason.RemoteConnect)
            ScheduleSystemRecovery("session_" + e.Reason.ToString().ToLowerInvariant());
    }

    private void OnUserPreferenceChanged(object sender, UserPreferenceChangedEventArgs e)
    {
        if (applicationExiting || config == null ||
            !string.Equals(config.theme, "system", StringComparison.OrdinalIgnoreCase)) return;
        try
        {
            BeginInvoke(new Action(delegate
            {
                bool previousDarkTheme = darkTheme;
                ApplyThemePalette();
                if (previousDarkTheme != darkTheme)
                {
                    RebuildShellForTheme();
                    ShowToast("界面已跟随 Windows 切换", "success");
                }
            }));
        }
        catch { }
    }

    private void ScheduleSystemRecovery(string reason)
    {
        if (applicationExiting || !config.setupCompleted || !config.startBridgeOnLaunch) return;
        pendingSystemRecoveryReason = reason;
        if (systemRecoveryTimer != null) return;
        systemRecoveryTimer = new System.Windows.Forms.Timer();
        systemRecoveryTimer.Interval = 2500;
        systemRecoveryTimer.Tick += delegate
        {
            systemRecoveryTimer.Stop();
            systemRecoveryTimer.Dispose();
            systemRecoveryTimer = null;
            string recoveryReason = string.IsNullOrWhiteSpace(pendingSystemRecoveryReason)
                ? "system_resume" : pendingSystemRecoveryReason;
            pendingSystemRecoveryReason = "";
            RecoverServicesAfterSystemChange(recoveryReason);
        };
        systemRecoveryTimer.Start();
        HostLog("SYSTEM RECOVERY scheduled=true reason=" + reason + " delay_ms=2500");
    }

    private void RecoverServicesAfterSystemChange(string reason)
    {
        if (applicationExiting || !config.setupCompleted || !config.startBridgeOnLaunch) return;
        if ((DateTime.UtcNow - lastSystemRecoveryAt).TotalSeconds < 10)
        {
            HostLog("SYSTEM RECOVERY skipped=true reason=throttled trigger=" + reason);
            return;
        }
        lastSystemRecoveryAt = DateTime.UtcNow;
        HostLog("SYSTEM RECOVERY begin=true reason=" + reason + " action=restart_bridge_and_capture");
        bridgeReady = false;
        StopCapture();
        StopKeyboardBridge();
        StartCapture();
        if (IsCapturing) ShowToast("系统恢复后正在重新连接遥控器", "info");
    }

    private void ApplyThemePalette()
    {
        string preference = config == null ? "light" : (config.theme ?? "light").Trim().ToLowerInvariant();
        darkTheme = preference == "dark" || (preference == "system" && WindowsUsesDarkApps());
        if (darkTheme)
        {
            ink = Color.FromArgb(229, 232, 239);
            muted = Color.FromArgb(153, 161, 177);
            violet = Color.FromArgb(126, 118, 213);
            green = Color.FromArgb(76, 174, 127);
            amber = Color.FromArgb(205, 157, 81);
            cyan = Color.FromArgb(79, 163, 181);
            coral = Color.FromArgb(205, 101, 110);
            line = Color.FromArgb(55, 59, 69);
            pageBackground = Color.FromArgb(25, 26, 31);
            sidebarBackground = Color.FromArgb(29, 30, 36);
            cardBackground = Color.FromArgb(35, 37, 44);
            surfaceBackground = Color.FromArgb(41, 43, 51);
            inputBackground = Color.FromArgb(31, 33, 39);
        }
        else
        {
            ink = Color.FromArgb(18, 30, 54);
            muted = Color.FromArgb(91, 104, 134);
            violet = Color.FromArgb(104, 82, 244);
            green = Color.FromArgb(10, 164, 104);
            amber = Color.FromArgb(229, 151, 39);
            cyan = Color.FromArgb(0, 153, 190);
            coral = Color.FromArgb(204, 70, 82);
            line = Color.FromArgb(220, 226, 239);
            pageBackground = Color.FromArgb(245, 247, 251);
            sidebarBackground = Color.FromArgb(249, 251, 255);
            cardBackground = Color.White;
            surfaceBackground = Color.FromArgb(246, 249, 253);
            inputBackground = Color.White;
        }
    }

    private void ApplyThemePreference(string preference)
    {
        string normalized = (preference ?? "light").Trim().ToLowerInvariant();
        string selected = normalized == "dark" ? "dark" : normalized == "system" ? "system" : "light";
        if (string.Equals(config.theme, selected, StringComparison.OrdinalIgnoreCase))
        {
            ShowToast(selected == "dark" ? "当前已是夜间模式" :
                selected == "system" ? "当前已跟随 Windows" : "当前已是白天模式", "info");
            return;
        }

        string previous = config.theme;
        config.theme = selected;
        bool saved = SaveConfig();
        ActionResult result = ActionResult.FromConfigurationApply("切换外观", "本地设置",
            selected == "dark" ? "已切换到夜间模式" :
            selected == "system" ? "已改为跟随 Windows" : "已切换到白天模式",
            saved, false, false);
        if (!saved)
        {
            config.theme = previous;
            ShowActionToast(result);
            return;
        }
        ApplyThemePalette();
        RebuildShellForTheme();
        ShowActionToast(result);
    }

    private void RebuildShellForTheme()
    {
        int page = currentPageIndex;
        SuspendLayout();
        if (toastTimer != null)
        {
            toastTimer.Stop();
            toastTimer.Dispose();
            toastTimer = null;
        }
        if (connectionBadge.Parent != null) connectionBadge.Parent.Controls.Remove(connectionBadge);

        DisposePageControls();

        var existing = new Control[Controls.Count];
        Controls.CopyTo(existing, 0);
        foreach (Control control in existing)
        {
            if (ReferenceEquals(control, content)) continue;
            Controls.Remove(control);
            DisposeOwnedControlResources(control);
            control.Dispose();
        }

        Controls.Clear();
        navButtons.Clear();
        toastPanel = null;
        toastIcon = null;
        toastLabel = null;
        BackColor = pageBackground;
        BuildShell();
        ShowPage(page);
        RefreshCaptureAskTheme();
        RefreshBrowserRemoteTheme();
        RefreshLiveHudTheme();
        RefreshContextDeckTheme();
        ResumeLayout(true);
        Invalidate(true);
    }

    private string GetUserStateRoot()
    {
        string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        if (string.IsNullOrWhiteSpace(localAppData)) return root;
        return Path.Combine(localAppData, "Vibe Flow Remote", "UserData");
    }

    private static string MigrateLegacyUserConfig(string legacyRoot, string stateRoot)
    {
        return MigrateLegacyUserConfig(legacyRoot, stateRoot, true);
    }

    private static string MigrateLegacyUserConfig(string legacyRoot, string stateRoot,
        bool includeDiscoveredLegacyRoots)
    {
        string destination = Path.Combine(stateRoot, "vibe-mic-config.json");
        int futureSchema;
        if (TryReadFutureUserConfigSchema(destination, out futureSchema) ||
            TryReadFutureUserConfigSchema(destination + ".bak", out futureSchema)) return "";
        string candidateContent;
        if (TryReadUserConfigCandidate(destination, out candidateContent)) return "";
        var legacyRoots = new List<string>();
        AddLegacyRootCandidate(legacyRoots, legacyRoot);
        if (includeDiscoveredLegacyRoots)
        {
            string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
            if (!string.IsNullOrWhiteSpace(localAppData))
                AddLegacyRootCandidate(legacyRoots, Path.Combine(localAppData, "Programs", "Vibe Flow Remote"));
            AddLegacyRootCandidate(legacyRoots, ReadStartupExecutableDirectory());
        }

        var candidates = new List<string> { destination + ".bak" };
        foreach (string candidateRoot in legacyRoots)
        {
            candidates.Add(Path.Combine(candidateRoot, "vibe-mic-config.json"));
            candidates.Add(Path.Combine(candidateRoot, "vibe-mic-config.json.bak"));
        }
        foreach (string candidate in candidates)
        {
            try
            {
                if (!TryReadUserConfigCandidate(candidate, out candidateContent)) continue;
                RestoreUserConfigCandidate(destination, candidateContent);
                return candidate;
            }
            catch { }
        }
        return "";
    }

    private static bool TryReadUserConfigCandidate(string path, out string content)
    {
        content = "";
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path)) return false;
        try
        {
            content = File.ReadAllText(path, Encoding.UTF8);
            object rawDocument = new JavaScriptSerializer().DeserializeObject(content);
            var document = rawDocument as Dictionary<string, object>;
            // A valid older or interrupted config may legitimately omit fields
            // introduced by a later schema. Deserialize it and let MigrateConfig
            // add defaults while preserving the fields the user already set.
            if (!IsReadableUserConfigDocument(document)) return false;
            VibeMicConfig parsed = new JavaScriptSerializer().Deserialize<VibeMicConfig>(content);
            return parsed != null;
        }
        catch
        {
            content = "";
            return false;
        }
    }

    private static bool IsReadableUserConfigDocument(Dictionary<string, object> document)
    {
        if (document == null) return false;
        int schemaVersion;
        if (!TryReadJsonInteger(document, "schemaVersion", out schemaVersion) ||
            schemaVersion <= 0 || schemaVersion > ConfigSchemaVersion) return false;
        object mappings;
        if (!document.TryGetValue("mappings", out mappings) ||
            !(mappings is Dictionary<string, object>)) return false;
        return true;
    }

    private static bool TryReadFutureUserConfigSchema(string path, out int schemaVersion)
    {
        schemaVersion = 0;
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path)) return false;
        try
        {
            object rawDocument = new JavaScriptSerializer().DeserializeObject(
                File.ReadAllText(path, Encoding.UTF8));
            var document = rawDocument as Dictionary<string, object>;
            return TryReadJsonInteger(document, "schemaVersion", out schemaVersion) &&
                schemaVersion > ConfigSchemaVersion;
        }
        catch { return false; }
    }

    private static bool IsCompleteUserConfigDocument(Dictionary<string, object> document)
    {
        if (document == null) return false;
        int schemaVersion;
        if (!TryReadJsonInteger(document, "schemaVersion", out schemaVersion) || schemaVersion <= 0 ||
            schemaVersion > ConfigSchemaVersion)
            return false;
        if (!HasJsonNumber(document, "captureSeconds") ||
            !HasJsonNumber(document, "gain") ||
            !HasJsonString(document, "voiceMode") ||
            !HasJsonBoolean(document, "setupCompleted") ||
            !HasJsonBoolean(document, "launchAtStartup") ||
            !HasJsonBoolean(document, "startBridgeOnLaunch") ||
            !HasJsonBoolean(document, "minimizeToTray") ||
            !HasJsonString(document, "audioEndpointName") ||
            !HasJsonString(document, "inputMethod") ||
            !HasJsonString(document, "inputMethodHotkey") ||
            !HasJsonNumber(document, "drainMs") ||
            !HasJsonString(document, "mappingPreset"))
            return false;
        object mappings;
        if (!document.TryGetValue("mappings", out mappings) ||
            !(mappings is Dictionary<string, object>)) return false;
        if (schemaVersion >= 11 && !HasJsonBoolean(document, "autoLevel")) return false;
        if (schemaVersion >= 13 && !HasJsonBoolean(document, "autoRouteVirtualMicrophone")) return false;
        if (schemaVersion >= 14 &&
            (!HasJsonNumber(document, "onboardingVersion") ||
             !HasJsonBoolean(document, "soundFeedbackEnabled"))) return false;
        if (schemaVersion >= 15 &&
            (!HasJsonNumber(document, "stableVoiceProfileVersion") ||
             !HasJsonString(document, "inputMethodTrigger") ||
             !HasJsonNumber(document, "providerStartupDelayMs") ||
             !HasJsonString(document, "audioProcessingMode"))) return false;
        if (schemaVersion >= 17 && !HasJsonBoolean(document, "autoCheckUpdates")) return false;
        if (schemaVersion >= 25 &&
            (!HasJsonNumber(document, "onboardingStep") ||
             !HasJsonBoolean(document, "resumeSetupAfterRestart") ||
             !HasJsonString(document, "theme"))) return false;
        if (schemaVersion >= 31 && !HasJsonString(document, "inputRoutingMode")) return false;
        if (schemaVersion >= 29)
        {
            object profiles;
            if (!document.TryGetValue("shortcutProfiles", out profiles) || !(profiles is object[]) ||
                !HasJsonString(document, "activeShortcutProfileId")) return false;
        }
        if (schemaVersion >= ConfigSchemaVersion &&
            (!HasJsonBoolean(document, "smartProfilesEnabled") ||
             !HasJsonBoolean(document, "smartProfileLocked") ||
             !HasJsonString(document, "smartProfileFallbackId")))
            return false;
        return true;
    }

    private static bool TryReadJsonInteger(Dictionary<string, object> document,
        string key, out int value)
    {
        value = 0;
        object raw;
        if (document == null || !document.TryGetValue(key, out raw) || raw == null || raw is bool)
            return false;
        try
        {
            value = Convert.ToInt32(raw, CultureInfo.InvariantCulture);
            return true;
        }
        catch { return false; }
    }

    private static bool HasJsonNumber(Dictionary<string, object> document, string key)
    {
        object raw;
        if (document == null || !document.TryGetValue(key, out raw) || raw == null ||
            raw is bool || raw is string) return false;
        try
        {
            Convert.ToDouble(raw, CultureInfo.InvariantCulture);
            return true;
        }
        catch { return false; }
    }

    private static bool HasJsonBoolean(Dictionary<string, object> document, string key)
    {
        object raw;
        return document != null && document.TryGetValue(key, out raw) && raw is bool;
    }

    private static bool HasJsonString(Dictionary<string, object> document, string key)
    {
        object raw;
        return document != null && document.TryGetValue(key, out raw) && raw is string;
    }

    private static void RestoreUserConfigCandidate(string destination, string content)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(destination));
        string backup = destination + ".bak";
        WriteTextAtomically(destination, content, backup);
        string previousBackup = backup + ".migration-previous";
        try
        {
            WriteTextAtomically(backup, content, previousBackup);
        }
        finally
        {
            try { if (File.Exists(previousBackup)) File.Delete(previousBackup); }
            catch { }
        }
    }

    private static int MigrateLegacyUserConfigForInstaller(string legacyRoot, string stateRoot)
    {
        legacyRoot = NormalizeInstallerPath(legacyRoot);
        stateRoot = NormalizeInstallerPath(stateRoot);
        MigrateLegacyUserConfig(legacyRoot, stateRoot, false);
        string destination = Path.Combine(stateRoot, "vibe-mic-config.json");
        string ignoredContent;
        if (TryReadUserConfigCandidate(destination, out ignoredContent)) return 0;
        bool configExists = File.Exists(destination) || File.Exists(destination + ".bak") ||
            File.Exists(Path.Combine(legacyRoot, "vibe-mic-config.json")) ||
            File.Exists(Path.Combine(legacyRoot, "vibe-mic-config.json.bak"));
        return configExists ? 12 : 0;
    }

    // The installer hands over a path taken straight from the registry, and that value ends with a backslash;
    // inside quotes the backslash escapes the closing quote, so the application is given a path containing a
    // quote. Measured: every install over an existing installation failed its configuration migration with
    // "路径中具有非法字符" and the installer told the user the old configuration could not be migrated, while a
    // clean install was unaffected. These cases are pinned so the trimming cannot quietly disappear.
    private static void RunInstallerPathSelfTests()
    {
        var cases = new List<string[]>();
        cases.Add(new string[] { "\"C:\\Program Files\\Vibe Flow\\\"", "C:\\Program Files\\Vibe Flow" });
        cases.Add(new string[] { "C:\\Program Files\\Vibe Flow\\", "C:\\Program Files\\Vibe Flow" });
        cases.Add(new string[] { "  \"C:\\Program Files\\Vibe Flow\"  ", "C:\\Program Files\\Vibe Flow" });
        cases.Add(new string[] { "\"C:\\Program Files\\Vibe Flow\"", "C:\\Program Files\\Vibe Flow" });
        // A drive root keeps its separator; removing it would turn "C:\" into "C:" and change its meaning.
        cases.Add(new string[] { "C:\\", "C:\\" });
        cases.Add(new string[] { "C:/", "C:/" });
        cases.Add(new string[] { "", "" });
        foreach (string[] pair in cases)
        {
            string actual = NormalizeInstallerPath(pair[0]);
            if (!string.Equals(actual, pair[1], StringComparison.Ordinal))
            {
                throw new InvalidOperationException("Installer path normalization turned '" + pair[0] +
                    "' into '" + actual + "' instead of '" + pair[1] + "'");
            }
        }
    }

    // Cleans a path that arrived from the installer's command line.
    //
    // A trailing separator inside quotes is the classic Windows command-line trap: `"...\Vibe Flow Remote\"`
    // leaves the closing quote inside the argument, because `\"` is read as an escaped quote. The installer
    // passes the previous install location straight from the registry, and that value ends in a backslash, so
    // `VibeFlow.exe --installer-config-migrate` died inside Path.Combine with "路径中具有非法字符" and the
    // installer reported that the old configuration could not be migrated — see the crash report this left,
    // which is how the cause was found. Trimming quotes and separators is safe because a Windows path cannot
    // contain a quote.
    private static string NormalizeInstallerPath(string value)
    {
        string path = (value ?? "").Trim().Trim('"').Trim();
        while (path.Length > 3 &&
            (path.EndsWith("\\", StringComparison.Ordinal) || path.EndsWith("/", StringComparison.Ordinal)))
        {
            path = path.Substring(0, path.Length - 1);
        }
        return path;
    }

    private static void AddLegacyRootCandidate(List<string> roots, string candidate)
    {
        if (string.IsNullOrWhiteSpace(candidate)) return;
        string normalized;
        try { normalized = Path.GetFullPath(candidate.Trim()); }
        catch { return; }
        foreach (string existing in roots)
            if (existing.Equals(normalized, StringComparison.OrdinalIgnoreCase)) return;
        roots.Add(normalized);
    }

    private static string ReadStartupExecutableDirectory()
    {
        try
        {
            using (RegistryKey key = Registry.CurrentUser.OpenSubKey(
                "Software\\Microsoft\\Windows\\CurrentVersion\\Run", false))
            {
                string command = key == null ? "" : Convert.ToString(key.GetValue("Vibe Flow"));
                int executableEnd = command.IndexOf(".exe", StringComparison.OrdinalIgnoreCase);
                if (executableEnd < 0) return "";
                string executablePath = command.Substring(0, executableEnd + 4).Trim().Trim('"');
                return Path.GetDirectoryName(executablePath) ?? "";
            }
        }
        catch { return ""; }
    }

    private static void DisposeOwnedControlResources(Control control)
    {
        if (control == null) return;
        foreach (Control child in control.Controls) DisposeOwnedControlResources(child);
        PictureBox picture = control as PictureBox;
        if (picture != null && picture.Image != null)
        {
            Image image = picture.Image;
            picture.Image = null;
            image.Dispose();
        }
        Button button = control as Button;
        if (button != null && button.Image != null)
        {
            Image image = button.Image;
            button.Image = null;
            image.Dispose();
        }
        IDisposable ownedTag = control.Tag as IDisposable;
        if (ownedTag != null)
        {
            control.Tag = null;
            ownedTag.Dispose();
        }
        // NewLabel and the button helpers allocate per-control fonts. Release
        // those explicit fonts during page teardown so repeated navigation does
        // not accumulate GDI handles; inherited/default fonts remain shared.
        if (control is Label || control is Button || control is TextBox || control is ComboBox || control is CheckBox)
        {
            Font font = control.Font;
            if (font != null && !font.Equals(SystemFonts.DefaultFont))
            {
                control.ResetFont();
                font.Dispose();
            }
        }
        Region region = control.Region;
        if (region != null)
        {
            control.Region = null;
            region.Dispose();
        }
    }

    private void DisposePageControls()
    {
        remoteVisual = null;
        heroPanel = null;
        heroTitle = null;
        heroSubtitle = null;
        heroStateLabel = null;
        activityLabel = null;
        bridgeButton = null;
        voiceBridgeStateLabel = null;
        overviewProfileLabel = null;
        actionReceiptGlyph = null;
        actionReceiptTitle = null;
        actionReceiptDetail = null;
        logBox = null;
        for (int i = 0; i < overviewStatusValues.Length; i++)
        {
            overviewStatusValues[i] = null;
            overviewStatusGlyphs[i] = null;
        }
        while (content.Controls.Count > 0)
        {
            Control control = content.Controls[0];
            content.Controls.RemoveAt(0);
            DisposeOwnedControlResources(control);
            control.Dispose();
        }
    }

    private void RunPageResourceTest()
    {
        using (Process process = Process.GetCurrentProcess())
        {
            var testTimer = System.Diagnostics.Stopwatch.StartNew();
            GC.Collect();
            GC.WaitForPendingFinalizers();
            int startUser = GetGuiResources(process.Handle, 1);
            int startGdi = GetGuiResources(process.Handle, 0);
            string failure = "";
            if (tray.ContextMenuStrip == null) SetupTray();
            ShowPage(PageHome);
            Control[] unavailableHudButtons = content.Controls.Find("liveHudButton", true);
            ToolStripItem[] unavailableHudMenuItems = tray.ContextMenuStrip == null
                ? new ToolStripItem[0]
                : tray.ContextMenuStrip.Items.Find("liveHudMenuItem", true);
            if (unavailableHudButtons.Length != 0 ||
                unavailableHudMenuItems.Length != 1 || !unavailableHudMenuItems[0].Enabled)
                failure = "Live HUD production entry is unavailable home_count=" + unavailableHudButtons.Length +
                    " home_enabled=" + (unavailableHudButtons.Length == 1 && unavailableHudButtons[0].Enabled) +
                    " tray_count=" + unavailableHudMenuItems.Length +
                    " tray_enabled=" + (unavailableHudMenuItems.Length == 1 && unavailableHudMenuItems[0].Enabled);
            if (failure.Length == 0)
            {
                ToolStripItem[] captureAskMenuItems = tray.ContextMenuStrip == null
                    ? new ToolStripItem[0]
                    : tray.ContextMenuStrip.Items.Find("captureAskTrayMenuItem", true);
                if (captureAskMenuItems.Length != 1 || !captureAskMenuItems[0].Enabled)
                    failure = "Capture & Ask production entry is missing home_count=" +
                        0 + " tray_count=" + captureAskMenuItems.Length;
            }
            Show();
            Activate();
            Application.DoEvents();
            IntPtr foregroundBeforeHud = GetForegroundWindow();
            if (failure.Length == 0)
            {
                ((ToolStripMenuItem)unavailableHudMenuItems[0]).PerformClick();
                Application.DoEvents();
                IntPtr foregroundAfterHud = GetForegroundWindow();
                bool visibleLiveHud = liveHud != null && liveHud.IsPresented;
                if (!visibleLiveHud || foregroundAfterHud != foregroundBeforeHud)
                    failure = "Live HUD did not present without activation visible=" + visibleLiveHud +
                        " foreground_before=" + foregroundBeforeHud + " foreground_after=" + foregroundAfterHud;
                if (failure.Length == 0)
                {
                    DateTime deadline = liveHudAutoHideAtUtc;
                    PublishFeedbackSnapshot();
                    Application.DoEvents();
                    if (liveHudAutoHideAtUtc != deadline)
                        failure = "Repeated Live HUD snapshot extended its auto-hide deadline";
                }
                if (failure.Length == 0)
                {
                    liveHud.HideInactive();
                    OnLiveHudDismissed(liveHud, EventArgs.Empty);
                    PublishFeedbackSnapshot();
                    Application.DoEvents();
                    if (liveHud.IsPresented)
                        failure = "Dismissed Live HUD reopened from an unchanged poll snapshot";
                    ((ToolStripMenuItem)unavailableHudMenuItems[0]).PerformClick();
                    Application.DoEvents();
                    if (!liveHud.IsPresented)
                        failure = "Explicit Live HUD entry did not clear session suppression";
                }
                if (failure.Length == 0)
                {
                    liveHud.HideInactive();
                    liveHudPresentationKey = "";
                    Hide();
                    Application.DoEvents();
                    IntPtr foregroundBeforeHiddenReceipt = GetForegroundWindow();
                    latestActionResult = ActionResult.Create("截图提问", "已验证目标", ActionState.Warning,
                        "截图动作已派发，请按住录音键描述问题", "",
                        "检查目标后手动确认发送", "CAPTURE-ASK-VISUAL-CONFIRMATION");
                    PublishFeedbackSnapshot();
                    Application.DoEvents();
                    bool hiddenHudPresented = liveHud.IsPresented;
                    IntPtr foregroundAfterHiddenReceipt = GetForegroundWindow();
                    bool hiddenHudHasReceipt = ControlTreeContainsText(liveHud,
                        "截图动作已派发，请按住录音键描述问题\r\n" +
                        "下一步：检查目标后手动确认发送\r\n" +
                        "错误码：CAPTURE-ASK-VISUAL-CONFIRMATION");
                    if (!hiddenHudPresented || foregroundAfterHiddenReceipt != foregroundBeforeHiddenReceipt ||
                        !hiddenHudHasReceipt)
                        failure = "Hidden Host did not present a non-activating Capture & Ask HUD receipt" +
                            " visible=" + hiddenHudPresented + " text=" + hiddenHudHasReceipt +
                            " foreground_before=" + foregroundBeforeHiddenReceipt +
                            " foreground_after=" + foregroundAfterHiddenReceipt;
                    Show();
                    Application.DoEvents();
                }
            }
            if (failure.Length == 0)
            {
                ShowContextDeck();
                Application.DoEvents();
                if (contextDeck == null || contextDeck.IsDisposed || !contextDeck.Visible)
                    failure = "Context Deck did not become visible";
                if (failure.Length == 0)
                {
                    Control[] mappingTables = contextDeck.Controls.Find("contextDeckMappingTable", true);
                    bool clippedMapping = mappingTables.Length != 1;
                    int mappingBottom = 0;
                    int mappingViewport = 0;
                    if (!clippedMapping)
                    {
                        Control table = mappingTables[0];
                        mappingViewport = table.ClientSize.Height - table.Padding.Bottom;
                        if (latestUiSnapshot == null ||
                            table.Controls.Count != latestUiSnapshot.Mappings.Count * 2) clippedMapping = true;
                        foreach (Control child in table.Controls)
                        {
                            mappingBottom = Math.Max(mappingBottom, child.Bottom);
                            if (child.Bottom > mappingViewport) clippedMapping = true;
                        }
                    }
                    if (clippedMapping) failure = "Context Deck mapping rows are clipped bottom=" +
                        mappingBottom + " viewport=" + mappingViewport + " tables=" + mappingTables.Length;
                    if (failure.Length == 0)
                    {
                        Control[] actionValues = contextDeck.Controls.Find("contextDeckActionValue", true);
                        if (actionValues.Length != 1)
                            failure = "Context Deck action detail is not exposed for clipping checks count=" +
                                actionValues.Length;
                        else
                        {
                            Control action = actionValues[0];
                            Size measured = TextRenderer.MeasureText(action.Text, action.Font,
                                new Size(Math.Max(1, action.ClientSize.Width), int.MaxValue),
                                TextFormatFlags.WordBreak | TextFormatFlags.TextBoxControl);
                            if (measured.Height > action.ClientSize.Height)
                                failure = "Context Deck action detail is clipped required=" + measured.Height +
                                    " available=" + action.ClientSize.Height;
                        }
                    }
                }
                ApplyVisualState("recording");
                Application.DoEvents();
                if (contextDeck != null && contextDeck.Visible)
                    failure = "Context Deck stayed visible while real audio was active";
                ApplyVisualState("stopped");
            }
            if (contextDeck != null && !contextDeck.IsDisposed) contextDeck.Close();
            for (int i = 0; i < 300; i++)
            {
                int page = NavigationPageIds[i % NavigationPageIds.Length];
                try
                {
                    ShowPage(page);
                    if (currentPageIndex != page || navButtons.Count != NavigationText.Length ||
                        NavigationText.Length != 6 ||
                        content.Controls.Count == 0 || !ControlTreeContainsText(content, ExpectedPageTitle(page)))
                    {
                        failure = "page=" + page + " failed to build or expose its title";
                        break;
                    }
                }
                catch (Exception ex)
                {
                    failure = "page=" + page + " exception=" + ex.GetType().Name + ": " + ex.Message;
                    break;
                }
                if (page == PageHome) Application.DoEvents();
            }
            ShowPage(PageHome);
            Application.DoEvents();
            GC.Collect();
            GC.WaitForPendingFinalizers();
            Application.DoEvents();
            int endUser = GetGuiResources(process.Handle, 1);
            int endGdi = GetGuiResources(process.Handle, 0);
            testTimer.Stop();
            int userDelta = endUser - startUser;
            int gdiDelta = endGdi - startGdi;
            string result = "UI resource test: switches=300 USER=" + startUser + "->" + endUser +
                " (delta " + userDelta + ") GDI=" + startGdi + "->" + endGdi + " (delta " + gdiDelta +
                ") duration_ms=" + testTimer.ElapsedMilliseconds +
                (failure.Length == 0 ? "" : " FAILURE " + failure);
            Console.WriteLine(result);
            string reportDirectory = Path.Combine(root, "tmp");
            Directory.CreateDirectory(reportDirectory);
            File.WriteAllText(Path.Combine(reportDirectory, "ui-resource-test.txt"), result, Encoding.UTF8);
            Environment.ExitCode = failure.Length == 0 && userDelta <= 120 && gdiDelta <= 50 ? 0 : 1;
        }
        config.minimizeToTray = false;
        Close();
    }

    private static bool IsStableCaptureRuntime(string runtime)
    {
        if (string.IsNullOrWhiteSpace(runtime)) return true;
        return runtime.IndexOf("recording_kernel=v1.0.3", StringComparison.OrdinalIgnoreCase) >= 0 &&
            runtime.IndexOf("voice_state_machine=v11", StringComparison.OrdinalIgnoreCase) >= 0;
    }

    private static int QueryConfigStartupForInstaller(string path)
    {
        // Same cleaning as the migration entry point: this path is assembled from a registry value by the
        // installer, and that value ends with a separator.
        path = NormalizeInstallerPath(path);
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path)) return 11;
        try
        {
            object parsed = new JavaScriptSerializer().DeserializeObject(File.ReadAllText(path, Encoding.UTF8));
            var document = parsed as Dictionary<string, object>;
            if (document == null || !document.ContainsKey("launchAtStartup")) return 11;
            object raw = document["launchAtStartup"];
            if (!(raw is bool)) return 11;
            bool setupCompleted = true;
            bool resumeSetupAfterRestart = false;
            object optional;
            if (document.TryGetValue("setupCompleted", out optional))
            {
                if (!(optional is bool)) return 11;
                setupCompleted = (bool)optional;
            }
            if (document.TryGetValue("resumeSetupAfterRestart", out optional))
            {
                if (!(optional is bool)) return 11;
                resumeSetupAfterRestart = (bool)optional;
            }
            bool shouldRegister = (bool)raw || (!setupCompleted && resumeSetupAfterRestart);
            return shouldRegister ? 10 : 0;
        }
        catch
        {
            return 11;
        }
    }

    private static string ClassifySessionEndFeedback(string lineText)
    {
        if (string.IsNullOrWhiteSpace(lineText)) return "";
        bool sessionEnd = lineText.IndexOf("WETYPE SESSION END", StringComparison.OrdinalIgnoreCase) >= 0 ||
            lineText.IndexOf("TRANSCRIPTION SESSION END", StringComparison.OrdinalIgnoreCase) >= 0;
        if (!sessionEnd) return "";
        if (lineText.IndexOf("audio_delivered=True", StringComparison.OrdinalIgnoreCase) < 0)
            return "error";
        // A delivered audio stream is not enough to claim that the provider
        // accepted the submit action. Keep this distinct so a missing or
        // closed provider panel cannot be presented as a successful handoff.
        return lineText.IndexOf("submitted=False", StringComparison.OrdinalIgnoreCase) >= 0
            ? "submission_failed" : "waiting";
    }

    private static string VoiceInputTargetSummary(FocusTargetDescriptor target)
    {
        if (target == null)
            return "尚未配置工作流 · 文字会跟随光标所在的应用";
        string status = FocusTargetService.VerificationStatusText(target);
        return target.Name + " · " + status + " · 录音前请先锁定";
    }

    private static bool IsInputTargetVerified(string provider, bool observed, bool ready)
    {
        return NormalizeProviderKey(provider) != "wechat" || (observed && ready);
    }

    private static bool IsImplicitChatGptTarget(FocusLearningCaptureResult capture)
    {
        if (capture == null || !capture.IsSuccess || capture.Descriptor == null) return false;
        FocusTargetDescriptor descriptor = capture.Descriptor;
        return string.Equals(FocusTargetDescriptor.NormalizeProcessName(descriptor.ProcessName),
                "chatgpt", StringComparison.OrdinalIgnoreCase) &&
            FocusTargetService.IsKnownEditableWebTarget(descriptor.ProcessName,
                descriptor.ClassName, descriptor.AutomationId, descriptor.ControlType);
    }

    private static string SessionEndFeedbackText(string state)
    {
        if (state == "submission_failed")
            return "音频已送达语音工具，但未确认提交；本次未执行发送。请重新聚焦输入框后重试，并在目标应用中目视确认文字。";
        return state == "waiting" ? "音频已交给语音工具 · 最终文字请目视确认" :
            "本次录音没有送出音频，未确认语音工具收到音频；可能是遥控器未输出真实音频或音频通道异常。请重新按住录音键重试；仍失败请打开连接与自检。";
    }

    private static string SessionEndFeedbackSummary(string state)
    {
        if (state == "submission_failed") return "未确认发送 · 请重新聚焦输入框后重试";
        return state == "waiting" ? "录音已结束 · 等待语音工具处理" :
            "未收到音频 · 请重新按住重试；仍失败请打开自检";
    }

    private static int SessionFeedbackDurationMs(string state)
    {
        return state == "waiting" || state == "error" || state == "submission_failed" ? 12000 : 3200;
    }

    private static bool SessionFeedbackToastMirrorsHero(string state)
    {
        return state != "waiting" && state != "error" && state != "submission_failed";
    }

    private static string TransientFeedbackTone(string state)
    {
        return state == "error" ? "error" : state == "processing" ? "warning" : "success";
    }

    private static bool ContainsFocusableInputControl(Control rootControl)
    {
        if (rootControl == null) return false;
        foreach (Control child in rootControl.Controls)
        {
            if (child.TabStop && (child is ButtonBase || child is TextBoxBase || child is ComboBox ||
                child is ListBox || child is ListView || child is TreeView || child is NumericUpDown))
                return true;
            if (ContainsFocusableInputControl(child)) return true;
        }
        return false;
    }

    private static int RunHostSelfTests()
    {
        try
        {
            const string weTypeDelivered =
                "WETYPE SESSION END generation=1 audio_delivered=True submitted=True panel_wait_ms=50";
            if (ClassifySessionEndFeedback(weTypeDelivered) != "waiting")
                throw new InvalidOperationException("Delivered WeChat session was not classified as waiting for visual confirmation");
            const string weTypeWithoutAudio =
                "WETYPE SESSION END generation=2 audio_delivered=False submitted=False panel_wait_ms=0";
            if (ClassifySessionEndFeedback(weTypeWithoutAudio) != "error")
                throw new InvalidOperationException("WeChat session without delivered audio was not classified as an error");
            const string weTypeSubmitFailed =
                "WETYPE SESSION END generation=3 audio_delivered=True submitted=False panel_wait_ms=5000";
            if (ClassifySessionEndFeedback(weTypeSubmitFailed) != "submission_failed")
                throw new InvalidOperationException("WeChat session without a dispatched submit action was reported as waiting");
            if (!ShouldScheduleProviderPasteFallback("wechat", weTypeDelivered, false, "processing", 1, 0) ||
                ShouldScheduleProviderPasteFallback("windows", weTypeDelivered, false, "processing", 1, 0) ||
                ShouldScheduleProviderPasteFallback("wechat", weTypeWithoutAudio, false, "processing", 2, 0) ||
                ShouldScheduleProviderPasteFallback("wechat", weTypeSubmitFailed, false, "processing", 3, 0) ||
                ShouldScheduleProviderPasteFallback("wechat", weTypeDelivered, true, "processing", 1, 0) ||
                ShouldScheduleProviderPasteFallback("wechat", weTypeDelivered, false, "recording", 1, 0) ||
                ShouldScheduleProviderPasteFallback("wechat", weTypeDelivered, false, "processing", 1, 1) ||
                ShouldScheduleProviderPasteFallback("wechat",
                    "WETYPE SESSION END generation=9 audio_delivered=False submitted=True panel_wait_ms=100",
                    false, "processing", 9, 0))
                throw new InvalidOperationException("WeChat provider paste fallback scheduling policy failed");
            const string weTypeSubmitDelivered =
                "WETYPE TRANSCRIPTION SUBMIT generation=10 sent=True audio_delivered=True";
            if (!ShouldScheduleProviderPasteFallback("wechat", weTypeSubmitDelivered,
                    false, "processing", 10, 0) ||
                ShouldScheduleProviderPasteFallback("wechat",
                    "WETYPE TRANSCRIPTION SUBMIT generation=11 sent=False audio_delivered=True",
                    false, "processing", 11, 0) ||
                ShouldScheduleProviderPasteFallback("wechat",
                    "WETYPE TRANSCRIPTION SUBMIT generation=12 sent=True audio_delivered=False",
                    false, "processing", 12, 0) ||
                ShouldScheduleProviderPasteFallback("wechat", weTypeSubmitDelivered,
                    false, "recording", 10, 0))
                throw new InvalidOperationException("WeChat early submit receipt paste policy failed");
            if (!ShouldHoldProviderHotkeyForSession("typeless") ||
                ShouldHoldProviderHotkeyForSession("wechat") ||
                ShouldHoldProviderHotkeyForSession("windows") ||
                ShouldHoldProviderHotkeyForSession("custom"))
                throw new InvalidOperationException("Provider hotkey hold policy does not match the hotkey-driven providers");
            if (!ShouldTapProviderHotkeyForSession("windows") ||
                ShouldTapProviderHotkeyForSession("wechat"))
                throw new InvalidOperationException("Provider hotkey tap policy does not match the Windows dictation provider");
            string submitFailureFeedback = SessionEndFeedbackText("submission_failed");
            if (submitFailureFeedback.IndexOf("未确认提交", StringComparison.Ordinal) < 0 ||
                submitFailureFeedback.IndexOf("未执行发送", StringComparison.Ordinal) < 0 ||
                submitFailureFeedback.IndexOf("重新聚焦输入框", StringComparison.Ordinal) < 0)
                throw new InvalidOperationException("Submit failure feedback lacks the input-focus impact or recovery action");
            if (SessionEndFeedbackSummary("submission_failed") != "未确认发送 · 请重新聚焦输入框后重试")
                throw new InvalidOperationException("Submit failure summary does not explain the recovery action");
            string noFocusSummary = VoiceInputTargetSummary(null);
            if (noFocusSummary.IndexOf("尚未配置工作流", StringComparison.Ordinal) < 0 ||
                noFocusSummary.IndexOf("跟随光标", StringComparison.Ordinal) < 0)
                throw new InvalidOperationException("Voice page does not clearly explain the missing input-target state");
            if (IsInputTargetVerified("wechat", false, false) ||
                IsInputTargetVerified("wechat", true, false) ||
                !IsInputTargetVerified("wechat", true, true) ||
                !IsInputTargetVerified("typeless", false, false))
                throw new InvalidOperationException("WeChat input-target verification was reported without evidence");
            var implicitChatGptTarget = new FocusTargetDescriptor
            {
                ProcessName = "chatgpt",
                ControlType = "Edit",
                ClassName = "ProseMirror",
                AutomationId = "",
                ParentFingerprint = "Window||ChatGPT",
                Strategy = "uia"
            };
            if (!IsImplicitChatGptTarget(FocusLearningCaptureResult.Success(implicitChatGptTarget)) ||
                IsImplicitChatGptTarget(FocusLearningCaptureResult.Failure("FOCUS-TARGET-NOT-EDITABLE")))
                throw new InvalidOperationException("Focused ChatGPT fallback target validation is not fail-closed");
            if (!FocusTargetService.MatchesStoredParentFingerprint(implicitChatGptTarget,
                    "Group||updated-chatgpt-composer", "ProseMirror") ||
                FocusTargetService.MatchesStoredParentFingerprint(implicitChatGptTarget,
                    "Group||updated-chatgpt-composer", "Button"))
                throw new InvalidOperationException("ChatGPT Smart Focus did not tolerate a changed parent fingerprint only for its stable editable composer");
            string noAudioFeedback = SessionEndFeedbackText("error");
            if (noAudioFeedback.IndexOf("未确认语音工具收到音频", StringComparison.Ordinal) < 0 ||
                noAudioFeedback.IndexOf("可能", StringComparison.Ordinal) < 0 ||
                noAudioFeedback.IndexOf("重新按住录音键重试", StringComparison.Ordinal) < 0 ||
                noAudioFeedback.IndexOf("打开连接与自检", StringComparison.Ordinal) < 0)
                throw new InvalidOperationException("Session failure feedback lacks impact, likely cause, or recovery action");
            if (SessionEndFeedbackSummary("error") != "未收到音频 · 请重新按住重试；仍失败请打开自检")
                throw new InvalidOperationException("Session failure summary is too long or lacks a visible recovery action");
            if (SessionFeedbackDurationMs("error") < 10000)
                throw new InvalidOperationException("Session failure feedback disappears before recovery guidance can be used");
            if (SessionFeedbackToastMirrorsHero("waiting") || SessionFeedbackToastMirrorsHero("error"))
                throw new InvalidOperationException("Session toast overwrites the complete hero feedback with its short summary");
            if (SessionFeedbackToastMirrorsHero("submission_failed"))
                throw new InvalidOperationException("Submit failure toast hides its recovery details");
            if (TransientFeedbackTone("processing") != "warning")
                throw new InvalidOperationException("Waiting-for-tool activity feedback uses a success color semantic");
            using (var unstartedProcess = new Process())
                if (IsProcessRunningSafely(unstartedProcess))
                    throw new InvalidOperationException("An unstarted Capture process was reported as running");
            if (IsProcessRunningSafely(null))
                throw new InvalidOperationException("A missing Capture process was reported as running");

            string runtimeFixtureRoot = Path.Combine(Path.GetTempPath(),
                "vibe-flow-capture-runtime-test-" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(runtimeFixtureRoot);
            try
            {
                System.Reflection.MethodInfo missingRuntimeMethod = typeof(VibeMicForm).GetMethod(
                    "GetMissingCaptureRuntimeFiles", System.Reflection.BindingFlags.Static |
                    System.Reflection.BindingFlags.NonPublic);
                if (missingRuntimeMethod == null)
                    throw new InvalidOperationException("Capture startup has no testable runtime completeness preflight");
                string[] missingRuntime = missingRuntimeMethod.Invoke(null,
                    new object[] { runtimeFixtureRoot, false }) as string[];
                if (missingRuntime == null || missingRuntime.Length != 3 ||
                    Array.IndexOf(missingRuntime, "VibeMicAtvvCapture.exe") < 0 ||
                    Array.IndexOf(missingRuntime, "NAudio.Core.dll") < 0 ||
                    Array.IndexOf(missingRuntime, "NAudio.Wasapi.dll") < 0)
                    throw new InvalidOperationException("Capture runtime preflight did not report every missing component");
                System.Reflection.MethodInfo runtimeFailureMethod = typeof(VibeMicForm).GetMethod(
                    "CaptureRuntimeFailureResult", System.Reflection.BindingFlags.Static |
                    System.Reflection.BindingFlags.NonPublic);
                if (runtimeFailureMethod == null)
                    throw new InvalidOperationException("Capture runtime preflight has no structured user-facing failure result");
                ActionResult runtimeFailure = runtimeFailureMethod.Invoke(null,
                    new object[] { missingRuntime, false }) as ActionResult;
                if (runtimeFailure == null || runtimeFailure.State != ActionState.Error || runtimeFailure.IsSuccess ||
                    runtimeFailure.ErrorCode != "VOICE-RUNTIME-INCOMPLETE" ||
                    runtimeFailure.Message.IndexOf("麦克风未启动", StringComparison.Ordinal) < 0 ||
                    runtimeFailure.ErrorReason.IndexOf("NAudio.Core.dll", StringComparison.Ordinal) < 0 ||
                    runtimeFailure.RecoveryAction.IndexOf("完整", StringComparison.Ordinal) < 0)
                    throw new InvalidOperationException("Capture runtime failure does not explain impact, cause, and recovery");

                System.Reflection.MethodInfo capturePreflightMethod = typeof(VibeMicForm).GetMethod(
                    "PrepareCaptureStartupRuntime", System.Reflection.BindingFlags.Static |
                    System.Reflection.BindingFlags.NonPublic);
                if (capturePreflightMethod == null)
                    throw new InvalidOperationException("Capture startup does not keep the keyboard Bridge independent from microphone runtime files");
                int bridgeStartAttempts = 0;
                ActionResult preflightFailure = capturePreflightMethod.Invoke(null, new object[]
                {
                    runtimeFixtureRoot,
                    false,
                    new Func<bool>(delegate { bridgeStartAttempts++; return true; })
                }) as ActionResult;
                if (bridgeStartAttempts != 1 || preflightFailure == null ||
                    preflightFailure.ErrorCode != "VOICE-RUNTIME-INCOMPLETE" ||
                    preflightFailure.ErrorReason.IndexOf("按键服务已启动", StringComparison.Ordinal) < 0)
                    throw new InvalidOperationException("Missing microphone files can still prevent or obscure keyboard Bridge startup");

                File.WriteAllBytes(Path.Combine(runtimeFixtureRoot, "VibeMicAtvvCapture.exe"), new byte[] { 1 });
                File.WriteAllBytes(Path.Combine(runtimeFixtureRoot, "NAudio.Core.dll"), new byte[] { 2 });
                File.WriteAllBytes(Path.Combine(runtimeFixtureRoot, "NAudio.Wasapi.dll"), new byte[] { 3 });
                missingRuntime = missingRuntimeMethod.Invoke(null,
                    new object[] { runtimeFixtureRoot, false }) as string[];
                if (missingRuntime == null || missingRuntime.Length != 3 ||
                    !Array.Exists(missingRuntime, delegate(string item)
                    {
                        return item.StartsWith("VibeMicAtvvCapture.exe", StringComparison.Ordinal);
                    }) ||
                    !Array.Exists(missingRuntime, delegate(string item)
                    {
                        return item.StartsWith("NAudio.Core.dll", StringComparison.Ordinal);
                    }) ||
                    !Array.Exists(missingRuntime, delegate(string item)
                    {
                        return item.StartsWith("NAudio.Wasapi.dll", StringComparison.Ordinal);
                    }))
                    throw new InvalidOperationException("Capture runtime preflight accepted corrupt runtime files");

                foreach (string runtimeFile in new[]
                {
                    "VibeMicAtvvCapture.exe", "NAudio.Core.dll", "NAudio.Wasapi.dll"
                })
                {
                    string verifiedSource = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, runtimeFile);
                    if (!File.Exists(verifiedSource))
                        throw new InvalidOperationException("Verified runtime self-test fixture is missing: " + runtimeFile);
                    File.Copy(verifiedSource, Path.Combine(runtimeFixtureRoot, runtimeFile), true);
                }
                missingRuntime = missingRuntimeMethod.Invoke(null,
                    new object[] { runtimeFixtureRoot, false }) as string[];
                if (missingRuntime == null || missingRuntime.Length != 0)
                    throw new InvalidOperationException("Capture runtime preflight rejected verified runtime files");
                ActionResult completePreflight = capturePreflightMethod.Invoke(null, new object[]
                {
                    runtimeFixtureRoot,
                    false,
                    new Func<bool>(delegate { bridgeStartAttempts++; return true; })
                }) as ActionResult;
                if (bridgeStartAttempts != 2 || completePreflight != null)
                    throw new InvalidOperationException("Complete microphone runtime preflight did not preserve keyboard Bridge startup");

                File.Copy(Application.ExecutablePath,
                    Path.Combine(runtimeFixtureRoot, "NAudio.Core.dll"), true);
                missingRuntime = missingRuntimeMethod.Invoke(null,
                    new object[] { runtimeFixtureRoot, false }) as string[];
                if (missingRuntime == null || !Array.Exists(missingRuntime, delegate(string item)
                    {
                        return item.StartsWith("NAudio.Core.dll", StringComparison.Ordinal);
                    }))
                    throw new InvalidOperationException("Capture runtime preflight accepted a managed assembly with the wrong NAudio identity");

                File.Delete(Path.Combine(runtimeFixtureRoot, "NAudio.Core.dll"));
                var wrongNAudioIdentity = new System.Reflection.AssemblyName("NAudio.Core");
                wrongNAudioIdentity.Version = new Version(1, 0, 0, 0);
                System.Reflection.Emit.AssemblyBuilder wrongNAudioAssembly =
                    AppDomain.CurrentDomain.DefineDynamicAssembly(wrongNAudioIdentity,
                        System.Reflection.Emit.AssemblyBuilderAccess.Save, runtimeFixtureRoot);
                System.Reflection.Emit.ModuleBuilder wrongNAudioModule =
                    wrongNAudioAssembly.DefineDynamicModule("NAudio.Core", "NAudio.Core.dll");
                wrongNAudioModule.DefineType("WrongVersionFixture").CreateType();
