    private void UpdateOverviewStatus()
    {
        if (overviewStatusValues[0] == null || overviewStatusValues[0].IsDisposed) return;
        SessionHealth latestHealth = GetLatestSessionHealth();
        LinkQualityVerdict liveQuality = CurrentLinkQuality();
        bool triggerOnlyOverview = IsTriggerOnlyVoiceMode();
        string providerValue = activeInputEngine != null && activeInputEngine.Known &&
            ActiveInputEngineBlocksConfiguredProvider() ? "前台：" + activeInputEngine.DisplayName :
            ProviderDisplayName(config.inputMethod);
        string[] values = {
            bridgeReady ? "已连接" : IsCapturing ? "连接中" : "待连接",
            bridgeReady ? (triggerOnlyOverview ? "由按键桥接处理" : "已接入") : "等待接入",
            liveQuality.Summary,
            providerValue,
            "不读取文字"
        };
        bool[] ready = { bridgeReady, bridgeReady, liveQuality.IsGood, IsProviderRunning(config.inputMethod), true };
        for (int i = 0; i < values.Length; i++)
        {
            if (overviewStatusValues[i] != null && !overviewStatusValues[i].IsDisposed) overviewStatusValues[i].Text = values[i];
            if (overviewStatusGlyphs[i] != null && !overviewStatusGlyphs[i].IsDisposed)
            {
                overviewStatusGlyphs[i].ForeColor = ready[i] ? (i == 4 ? green : i < 2 ? violet : cyan) : amber;
            }
        }
        UpdateActionReceipt(ReadKeyboardBridgeHealth());
    }

    private string GestureMappingSummary(string shortKey, string longKey)
    {
        string shortText = MappingCardActionText(GetMapping(shortKey, DefaultConfigurableAction(shortKey)));
        string longText = MappingCardActionText(GetMapping(longKey, DefaultConfigurableAction(longKey)));
        // "· 长按 未设置" is noise in a summary cell, and it was ellipsising away the half that matters. The long layer is
        // named only when it actually has an action of its own.
        bool longSet = !string.IsNullOrEmpty(longText) && longText != "未设置" && longText != "未配置" &&
            !longText.Equals("none", StringComparison.OrdinalIgnoreCase);
        return longSet ? "短按 " + shortText + " · 长按 " + longText : "短按 " + shortText;
    }

    private string DirectionMappingSummary()
    {
        string up = MappingCardActionText(GetMapping("上键", "up"));
        string down = MappingCardActionText(GetMapping("下键", "down"));
        return "↑ " + up + "  ↓ " + down;
    }

    private void UpdateActionReceipt(BridgeHealthSnapshot receipt)
    {
        if (actionReceiptTitle == null || actionReceiptTitle.IsDisposed ||
            actionReceiptDetail == null || actionReceiptDetail.IsDisposed) return;
        ShortcutProfileConfig active = ActiveShortcutProfile(config);
        string activeName = receipt != null && !string.IsNullOrWhiteSpace(receipt.SmartEffectiveProfileName)
            ? receipt.SmartEffectiveProfileName : active == null ? "当前 Profile" : active.name;
        if (receipt == null || receipt.LastExecutionSequence <= 0)
        {
            actionReceiptTitle.Text = "等待按键操作";
            actionReceiptDetail.Text = activeName + " · 按下已配置按键后，这里显示真实结果";
            if (actionReceiptGlyph != null && !actionReceiptGlyph.IsDisposed)
            {
                actionReceiptGlyph.Text = "\uE946";
                actionReceiptGlyph.ForeColor = muted;
            }
            return;
        }
        string label = string.IsNullOrWhiteSpace(receipt.LastExecutionLabel)
            ? receipt.LastExecutionButton : receipt.LastExecutionLabel;
        string trigger = string.IsNullOrWhiteSpace(receipt.LastExecutionTrigger)
            ? "单击" : receipt.LastExecutionTrigger;
        string action = CustomActionText(receipt.LastExecutionAction);
        string normalizedAction = (receipt.LastExecutionAction ?? "").Trim().ToLowerInvariant();
        bool disabledAction = normalizedAction.Length == 0 || normalizedAction == "none" || normalizedAction == "passthrough";
        actionReceiptTitle.Text = label + " · " + trigger + " · " + action;
        string profileName = string.IsNullOrWhiteSpace(receipt.LastExecutionProfileName)
            ? activeName : receipt.LastExecutionProfileName;
        string age = receipt.LastExecutionAgeSeconds < 5 ? "刚刚" :
            receipt.LastExecutionAgeSeconds < 60 ? ((int)receipt.LastExecutionAgeSeconds) + " 秒前" :
            receipt.LastExecutionAtUtc.ToLocalTime().ToString("HH:mm:ss");
        actionReceiptDetail.Text = profileName + " · " + (disabledAction ? "未配置动作，不是连接故障" :
            receipt.LastExecutionSuccess ? "执行成功" : "执行失败，请打开自检查看") + " · " + age;
        if (actionReceiptGlyph != null && !actionReceiptGlyph.IsDisposed)
        {
            actionReceiptGlyph.Text = disabledAction ? "\uE946" : receipt.LastExecutionSuccess ? "\uE73E" : "\uEA39";
            actionReceiptGlyph.ForeColor = disabledAction ? amber : receipt.LastExecutionSuccess ? green : coral;
        }
    }

    // The dedicated 工作流 page: everything about the favourite applications lives here —
    // adding, learning, saving, the shortcut/workflow mode, opening and deleting. The voice
    // page keeps only the current state and a way in.
    private void BuildWorkflowPage()
    {
        AddPageTitle("工作流", "把文字送进你常用的应用：添加、学习、保存，之后交给录音键");
        // One card, and one place an application is configured.
        //
        // The page used to stack two cards that answered the same question — 常用应用 and 应用工作流 — so the user had
        // to read both and work out which list was "theirs". The favourite applications are the user's own list and
        // come first; the applications a key Profile binds that still need a workflow follow underneath the same
        // card, which keeps the one-line-per-application form that was chosen over listing every application.
        List<WorkflowCard> cards = BuildCurrentWorkflowCards();
        var pending = new List<WorkflowCard>();
        foreach (WorkflowCard card in cards)
        {
            if (!card.IsReady) pending.Add(card);
        }
        int cardHeight = BuildFavoriteAppsCard(content, 100, pending, WorkflowCards.Summarize(cards));
        var hint = NewLabel("提示：按住录音键时，文字会进入标着「当前」的应用；点「打开」可把未运行的应用启动并定位到输入框。",
            9f, FontStyle.Regular, muted);
        hint.Location = new Point(40, 100 + cardHeight + 16);
        hint.Size = new Size(900, 26);
        content.Controls.Add(hint);
        content.AutoScrollMinSize = new Size(1000, 100 + cardHeight + 60);
    }

    // The per-application workflow status, and the only place it appears.
    // The second section of the workflow card, and the only place it appears.
    //
    // It reads as work remaining rather than as a list of faults: applications that are ready are counted in the
    // summary line and not listed, and each remaining application takes one line — its name, the one thing it is
    // missing, and the single action that moves it forward — instead of the four-line block (正确状态 / 当前状态 /
    // 原因 [VF-WORKFLOW-…] / 下一步) it used to occupy on the self-check page. It sits inside the favourites card now
    // rather than in a card of its own.
    private void AddWorkflowStatusSection(Control card, IList<WorkflowCard> pending, string summaryText, int top)
    {
        var divider = new Panel();
        divider.Location = new Point(18, top);
        divider.Size = new Size(924, 1);
        divider.BackColor = line;
        card.Controls.Add(divider);
        // A plain sub-heading, not SectionTitle: the icon glyph that helper draws rendered as a small meaningless
        // mark in front of the title here. The heading also lost the word 工作流, because the rows below it are
        // about what still needs doing rather than about a feature name.
        var title = NewLabel("还需要处理", 11.5f, FontStyle.Bold, ink);
        // 26 matches the favourites panel's own left edge and its empty-state heading, so the two sections of the
        // card line up instead of starting at slightly different places.
        // 44 = the card's 18 px inset plus the favourites panel's own 26 px content inset: the two sections share
        // one left edge, which is what "the two lists are not aligned" was about.
        title.Location = new Point(44, top + 12);
        // 190 keeps the heading's box clear of the summary, which starts at 240: at 200 wide the shift to 44 ran four
        // pixels into it, and the geometry check reported the overlap.
        title.Size = new Size(190, 28);
        var summary = NewLabel(summaryText, 8.7f, FontStyle.Regular, muted);
        summary.Location = new Point(240, top + 14);
        summary.Size = new Size(682, 24);
        summary.TextAlign = ContentAlignment.MiddleRight;
        card.Controls.Add(title);
        card.Controls.Add(summary);
        for (int i = 0; i < pending.Count; i++) AddWorkflowStatusRow(card, pending[i], top + 46 + i * 44);
    }

    // One application, one line. The state chip and the action both come from the card model, so the line cannot
    // claim something the model does not say, and the action is the same dispatcher the self-check page used.
    private void AddWorkflowStatusRow(Control parent, WorkflowCard card, int y)
    {
        var row = new Panel();
        row.Location = new Point(18, y);
        row.Size = new Size(924, 44);
        row.BackColor = Color.Transparent;
        row.Paint += delegate(object sender, PaintEventArgs e)
        {
            using (var pen = new Pen(line)) e.Graphics.DrawLine(pen, 0, row.Height - 1, row.Width, row.Height - 1);
        };
        string gap = card.Gaps.Count > 0 ? card.Gaps[0] : "";
        bool unverified = string.Equals(gap, WorkflowCards.GapTargetUnverified, StringComparison.Ordinal);
        Color statusColor = card.State == "pass" ? green : unverified ? cyan : amber;
        // The application's own icon, looked up in the machine's catalogue first.
        //
        // This row asked the *running process* for its executable, which returns nothing for an application that is
        // installed and not running, so most rows fell back to a generated letter tile even though the catalogue
        // already holds the real icon — 91 of 95 entries on this machine. The catalogue is consulted first now, and
        // the tile remains only as the last resort. The tile background matters because several application icons
        // carry transparency for a white or a dark background and read as absent when drawn straight onto a card.
        string iconSource;
        Image rowIcon = AppIcons.For(card.ProcessName, card.Title, "",
            InstalledAppCatalog.IconForProcess(card.ProcessName), out iconSource);
        Color iconTile = darkTheme ? Color.FromArgb(45, 47, 56) : Color.FromArgb(243, 245, 250);
        var iconPanel = new Panel();
        // 40 and 84 are the favourites panel's own row columns (its tile and its text), so the two lists share one
        // left edge instead of starting 36 px apart.
        iconPanel.Location = new Point(40, 5);
        iconPanel.Size = new Size(30, 30);
        iconPanel.BackColor = Color.Transparent;
        iconPanel.Paint += delegate(object sender, PaintEventArgs e)
        {
            AppIcons.DrawTile(e.Graphics, rowIcon, new Rectangle(0, 0, iconPanel.Width, iconPanel.Height),
                iconTile, 8);
        };
        var title = NewLabel(card.Title, 9.4f, FontStyle.Bold, ink);
        title.Location = new Point(84, 9);
        title.Size = new Size(240, 22);
        title.AutoEllipsis = true;
        // The state sits on one line with the name, and the sentence that used to run underneath it — 「键位 … ·
        // 工作流 未设置 · 语音工具 …」 — is gone: it repeated what the state already says in the vocabulary of the
        // configuration file rather than of the user.
        var state = NewLabel(WorkflowCards.ShortGapLabel(gap), 8.4f, FontStyle.Bold, statusColor);
        state.Location = new Point(330, 10);
        state.Size = new Size(200, 22);
        row.Controls.Add(iconPanel);
        row.Controls.Add(title);
        row.Controls.Add(state);
        if (!string.IsNullOrEmpty(card.Action))
        {
            var action = SecondaryButton(card.ActionText, new Point(762, 2), new Size(144, 36));
            action.Font = new Font("Microsoft YaHei UI", 8.3f, FontStyle.Bold);
            action.Click += delegate { HandleSelfCheckAction(card.Action); };
            row.Controls.Add(action);
        }
        parent.Controls.Add(row);
    }

    private void BuildVoicePage()
    {
        AddPageTitle("语音", "遥控器负责收音；转写与整理能力由所选工具设置");
        // The redesigned Smart Focus surface comes first: the one thing a new user must set.
        int favoriteCardHeight = 0;
        var card = NewCard(new Point(34, 116 + favoriteCardHeight), new Size(960, 716));
        card.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        card.Controls.Add(SectionTitle("听写通道", "\uE720", new Point(30, 24)));

        var stateBand = new Panel();
        stateBand.Location = new Point(30, 64);
        stateBand.Size = new Size(900, 62);
        stateBand.BackColor = IsCapturing ? StatusSurface("ready") : surfaceBackground;
        voiceBridgeStateLabel = NewLabel(IsCapturing ? "●  已就绪 · " + VoiceReadyInstruction(config.voiceMode) : "●  语音桥接已暂停", 10.5f, FontStyle.Bold,
            IsCapturing ? green : muted);
        voiceBridgeStateLabel.Location = new Point(22, 19);
        voiceBridgeStateLabel.AutoSize = true;
        bool stableVoiceProfile = HasStableVoiceProfile(config);
        bool advancedAudioUnlocked = !stableVoiceProfile;
        var profileBadge = NewLabel(stableVoiceProfile ? "●  语音参数已应用（v" + StableVoiceProfileVersion + "）" : "●  参数已自定义", 8.8f, FontStyle.Bold,
            stableVoiceProfile ? green : amber);
        profileBadge.Location = new Point(650, 20);
        profileBadge.Size = new Size(225, 26);
        profileBadge.TextAlign = ContentAlignment.MiddleRight;
        stateBand.Controls.Add(voiceBridgeStateLabel);
        stateBand.Controls.Add(profileBadge);
        ApplyRoundedRegion(stateBand, 8);
        card.Controls.Add(stateBand);

        AddFieldLabel(card, "转写工具", 152);
        var provider = StyledCombo(new Point(220, 148), new Size(260, 38));
        provider.Items.AddRange(new object[] { "微信输入法", "Typeless", "Windows 语音输入", "其他语音工具" });
        provider.SelectedIndex = ProviderIndex(config.inputMethod);
        var providerStatus = NewLabel(ProviderStatusText(config.inputMethod), 9.2f, FontStyle.Bold,
            IsProviderRunning(config.inputMethod) ? green : amber);
        providerStatus.Location = new Point(505, 154);
        providerStatus.Size = new Size(400, 28);
        card.Controls.Add(provider);
        card.Controls.Add(providerStatus);

        AddFieldLabel(card, "启动快捷键", 206);
        var hotkey = StyledTextBox(config.inputMethodHotkey, new Point(220, 202), new Size(220, 34));
        var triggerMode = StyledCombo(new Point(458, 200), new Size(184, 38));
        PopulateTriggerModeOptions(triggerMode, config.inputMethod);
        triggerMode.SelectedIndex = NormalizeProviderKey(config.inputMethod) == "wechat" ? 0 :
            config.inputMethodTrigger == "hold" ? 1 : 0;
        var hotkeyHelp = NewLabel(ProviderHotkeyHelp(config.inputMethod, config.inputMethodTrigger), 9f, FontStyle.Regular, muted);
        hotkeyHelp.Location = new Point(658, 207);
        hotkeyHelp.Size = new Size(242, 25);
        card.Controls.Add(hotkey);
        card.Controls.Add(triggerMode);
        card.Controls.Add(hotkeyHelp);

        AddFieldLabel(card, "录音方式", 260);
        var voiceMode = NewLabel("按住说话 · 松开结束", 10f, FontStyle.Bold, violet);
        voiceMode.Location = new Point(220, 256);
        voiceMode.Size = new Size(270, 38);
        voiceMode.TextAlign = ContentAlignment.MiddleLeft;
        var voiceModeHelp = NewLabel(VoiceModeHelp(config.voiceMode), 9f, FontStyle.Regular, muted);
        voiceModeHelp.Location = new Point(548, 263);
        voiceModeHelp.Size = new Size(370, 25);
        card.Controls.Add(voiceMode);
        card.Controls.Add(voiceModeHelp);

        AddFieldLabel(card, "声音处理", 314);
        var processing = StyledCombo(new Point(220, 310), new Size(260, 38));
        processing.Items.AddRange(new object[] { "清晰增强（推荐）", "原始直通" });
        processing.SelectedIndex = config.audioProcessingMode == "transparent" ? 1 : 0;
        processing.Enabled = advancedAudioUnlocked;
        var processingHelp = NewLabel(stableVoiceProfile
            ? "已锁定为真机验证的清晰增强模式。"
            : config.audioProcessingMode == "transparent"
            ? "仅做格式转换，适合排查原始音频。"
            : "稳定补偿轻声，孤立尖峰不会压低整段语音。", 9f, FontStyle.Regular, muted);
        processingHelp.Location = new Point(505, 317);
        processingHelp.Size = new Size(390, 25);
        card.Controls.Add(processing);
        card.Controls.Add(processingHelp);

        AddFieldLabel(card, "收音灵敏度", 368);
        var gainHelp = NewLabel(stableVoiceProfile
            ? "已锁定为真机验证值 1.0×；普通使用无需调整。"
            : "建议保持 1.0×；仅在排障时小幅调整。", 9.2f, FontStyle.Regular, muted);
        gainHelp.Location = new Point(220, 370);
        gainHelp.Size = new Size(520, 24);
        card.Controls.Add(gainHelp);
        var gain = new TrackBar();
        gain.Location = new Point(212, 396);
        gain.Size = new Size(390, 44);
        gain.Minimum = 5;
        gain.Maximum = 40;
        gain.Value = Math.Max(5, Math.Min(40, (int)(config.gain * 10)));
        gain.Enabled = advancedAudioUnlocked;
        var gainValue = NewLabel((gain.Value / 10.0).ToString("0.0") + "×", 10f, FontStyle.Bold, violet);
        gainValue.Location = new Point(620, 404);
        gainValue.Size = new Size(70, 28);
        gain.Scroll += delegate { gainValue.Text = (gain.Value / 10.0).ToString("0.0") + "×"; };
        card.Controls.Add(gain);
        card.Controls.Add(gainValue);

        bool triggerOnlyVoicePage = IsTriggerOnlyVoiceMode();
        var autoRoute = StyledCheck(triggerOnlyVoicePage ? "免驱动模式：不切换默认录音设备" :
            "听写时自动使用遥控器麦克风（推荐）", !triggerOnlyVoicePage && config.autoRouteVirtualMicrophone,
            new Point(212, 444));
        autoRoute.Size = new Size(330, 34);
        autoRoute.AutoCheck = advancedAudioUnlocked && !triggerOnlyVoicePage;
        autoRoute.TabStop = advancedAudioUnlocked && !triggerOnlyVoicePage;
        if (!advancedAudioUnlocked || triggerOnlyVoicePage) autoRoute.ForeColor = muted;
        var routeHelp = NewLabel(triggerOnlyVoicePage ? "安装 VB-CABLE 后可改回遥控器麦克风" :
            "结束听写后自动恢复原来的 Windows 麦克风", 8.9f, FontStyle.Regular, muted);
        routeHelp.Location = new Point(548, 451);
        routeHelp.Size = new Size(350, 24);
        card.Controls.Add(autoRoute);
        card.Controls.Add(routeHelp);

        bool cableInputReady = HasCableInput();
        bool cableOutputReady = HasCableOutput();
        bool cableEndpointReady = string.Equals(config.audioEndpointName, StableVoiceEndpoint,
            StringComparison.OrdinalIgnoreCase);
        bool cableReady = cableInputReady && cableOutputReady && cableEndpointReady;
        string cableStateText = (cableInputReady ? "✓" : "!") + "  CABLE Input（播放端）" +
            (cableInputReady ? " 已检测" : " 未检测") + "    " +
            (cableOutputReady ? "✓" : "!") + "  CABLE Output（录音端）" +
            (cableOutputReady ? " 已检测" : " 未检测");
        var cableState = NewLabel(cableStateText, 9.6f, FontStyle.Bold,
            cableReady ? green : coral);
        cableState.Location = new Point(220, 482);
        cableState.Size = new Size(670, 24);
        cableState.TextAlign = ContentAlignment.MiddleLeft;
        card.Controls.Add(cableState);
        var cableEndpoint = NewLabel("当前播放端点：" +
            (string.IsNullOrWhiteSpace(config.audioEndpointName) ? "未选择" : config.audioEndpointName) +
            (cableEndpointReady ? " · 与稳定语音档案一致" : " · 需要改回 CABLE Input"),
            8.8f, FontStyle.Regular, cableEndpointReady ? muted : amber);
        // The two status lines and the buttons below them are stacked by coordinate, and the rows
        // used to overlap: the state line ended at 508 while this line began at 502, so the green
        // CABLE status and the grey endpoint line collided by 6 px at 100% DPI. Measured with
        // scripts/check-ui-geometry.ps1, which reports sibling controls whose rectangles intersect.
        cableEndpoint.Location = new Point(220, 506);
        cableEndpoint.Size = new Size(670, 18);
        cableEndpoint.TextAlign = ContentAlignment.MiddleLeft;
        card.Controls.Add(cableEndpoint);

        var start = PrimaryButton(IsCapturing ? "暂停语音桥接" : "启动语音桥接", new Point(220, 524), new Size(152, 44));
        start.Click += delegate { ToggleCapture(); start.Text = IsCapturing ? "暂停语音桥接" : "启动语音桥接"; };
        var test = SecondaryButton("测试所选工具", new Point(386, 524), new Size(148, 44));
        test.Click += delegate { TestVoiceHotkey(); };
        var sound = SecondaryButton(config.inputMethod == "typeless" ? "获取所选工具" : "检查麦克风设置",
            new Point(548, 524), new Size(158, 44));
        sound.Click += delegate { OpenProviderHelp(config.inputMethod); };
        var profileAction = SecondaryButton(stableVoiceProfile ? "调整高级参数" : "恢复稳定参数", new Point(720, 524), new Size(170, 44));
        profileAction.Tag = stableVoiceProfile ? "unlock" : "restore";
        profileAction.Click += delegate
        {
            if (string.Equals(profileAction.Tag as string, "unlock", StringComparison.OrdinalIgnoreCase))
            {
                DialogResult confirmation = MessageBox.Show(
                    "稳定档案已经通过真机反复验证。只有在排查特殊设备问题时才建议修改声音处理、灵敏度或麦克风路由。\r\n\r\n是否继续？",
                    "调整高级音频参数", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);
                if (confirmation != DialogResult.Yes) return;
                advancedAudioUnlocked = true;
                processing.Enabled = true;
                gain.Enabled = true;
                autoRoute.Enabled = true;
                processingHelp.Text = config.audioProcessingMode == "transparent" ? "仅做格式转换，适合排查原始音频。" : "稳定补偿轻声，孤立尖峰不会压低整段语音。";
                gainHelp.Text = "建议保持 1.0×；仅在排障时小幅调整。";
                profileAction.Text = "恢复稳定参数";
                profileAction.Tag = "restore";
                ShowToast("高级参数已解锁，修改后可随时恢复稳定档案", "info");
                return;
            }
            VibeMicConfig previousConfig = CloneConfiguration(config);
            bool captureWasRunning = IsCapturing;
            ApplyStableVoiceProfile(config);
            ActionResult result = PersistVoiceConfigurationMutationCore(
                "恢复稳定语音参数", "已恢复真机验证的稳定语音参数",
                SaveConfig, delegate { config = CloneConfiguration(previousConfig); },
                captureWasRunning, RestartCaptureForAudioSettings);
            ShowPage(PageVoice);
            ShowActionToast(result);
        };
        card.Controls.Add(start);
        card.Controls.Add(test);
        card.Controls.Add(sound);
        card.Controls.Add(profileAction);

        AddFieldLabel(card, "工作流", 582);
        voiceFocusTargetLabel = NewLabel(FavoriteAppSummaryText(), 9.2f,
            FontStyle.Bold, DefaultFocusTarget() == null ? amber : FocusTargetStatusColor());
        voiceFocusTargetLabel.Location = new Point(220, 580);
        voiceFocusTargetLabel.Size = new Size(430, 34);
        voiceFocusTargetLabel.TextAlign = ContentAlignment.MiddleLeft;
        voiceFocusTargetButton = PrimaryButton("添加应用", new Point(666, 576), new Size(224, 42));
        voiceFocusTargetButton.Name = "voiceFocusTargetButton";
        voiceFocusTargetButton.Click += delegate
        {
            // Redesigned flow: pick a running application from a list, then click its
            // input box once. No names are typed and nothing else needs to be learned.
            BeginFavoriteAppLearning();
        };
        card.Controls.Add(voiceFocusTargetLabel);
        // The action lives on the 常用应用 card; this row is informational only.

        var note = NewLabel(VoiceModeNote(config.inputMethod, config.autoRouteVirtualMicrophone), 9.3f, FontStyle.Regular, muted);
        note.Location = new Point(30, 634);
        note.Size = new Size(880, 62);
        card.Controls.Add(note);

        // The redesigned Smart Focus surface lives on its own card, right below the
        // audio chain, and only ever asks for clicks.
        // The voice page only reports which application receives the text and points at the
        // 工作流 page; every configuration lives there.

        bool updating = false;
        Action markProfileCustomized = delegate
        {
            profileBadge.Text = "●  参数已自定义";
            profileBadge.ForeColor = amber;
            profileAction.Text = "恢复稳定参数";
            profileAction.Tag = "restore";
        };
        gain.MouseUp += delegate
        {
            VibeMicConfig previousConfig = CloneConfiguration(config);
            bool captureWasRunning = IsCapturing;
            config.gain = gain.Value / 10.0;
            markProfileCustomized();
            ActionResult result = PersistVoiceConfigurationMutationCore(
                "调整收音灵敏度", "收音灵敏度已保存", SaveConfig,
                delegate { config = CloneConfiguration(previousConfig); },
                captureWasRunning, RestartCaptureForAudioSettings);
            if (result.State == ActionState.Error) ShowPage(PageVoice);
            ShowActionToast(result);
        };
        provider.SelectedIndexChanged += delegate
        {
            if (updating) return;
            VibeMicConfig previousConfig = CloneConfiguration(config);
            bool captureWasRunning = IsCapturing;
            updating = true;
            ApplyProviderProfile(config, ProviderKeyFromIndex(provider.SelectedIndex));
            hotkey.Text = config.inputMethodHotkey;
            PopulateTriggerModeOptions(triggerMode, config.inputMethod);
            triggerMode.SelectedIndex = NormalizeProviderKey(config.inputMethod) == "wechat" ? 0 :
                config.inputMethodTrigger == "hold" ? 1 : 0;
            hotkeyHelp.Text = ProviderHotkeyHelp(config.inputMethod, config.inputMethodTrigger);
            providerStatus.Text = ProviderStatusText(config.inputMethod);
            providerStatus.ForeColor = IsProviderRunning(config.inputMethod) ? green : amber;
            note.Text = VoiceModeNote(config.inputMethod, config.autoRouteVirtualMicrophone);
            updating = false;
            ActionResult result = PersistVoiceConfigurationMutationCore(
                "更改语音工具", "语音工具设置已保存", SaveConfig,
                delegate { config = CloneConfiguration(previousConfig); },
                captureWasRunning, RestartCaptureForAudioSettings);
            BeginInvoke(new Action(delegate
            {
                ShowPage(PageVoice);
                ShowActionToast(result);
            }));
        };
        hotkey.Leave += delegate
        {
            string value = hotkey.Text.Trim().ToLowerInvariant();
            if (!IsValidTranscriptionHotkey(value))
            {
                hotkey.Text = config.inputMethodHotkey;
                Toast("快捷键格式不正确，请使用例如 ctrl+win、rightalt 或 win+h");
                return;
            }
            if (value == config.inputMethodHotkey) return;
            VibeMicConfig previousConfig = CloneConfiguration(config);
            bool captureWasRunning = IsCapturing;
            config.inputMethodHotkey = value;
            if (NormalizeProviderKey(config.inputMethod) == "wechat")
            {
                config.inputMethodTrigger = "toggle";
                updating = true;
                triggerMode.SelectedIndex = 0;
                updating = false;
                hotkeyHelp.Text = ProviderHotkeyHelp(config.inputMethod, config.inputMethodTrigger);
            }
            ActionResult result = PersistVoiceConfigurationMutationCore(
                "更改语音快捷键", "语音快捷键已保存", SaveConfig,
                delegate { config = CloneConfiguration(previousConfig); },
                captureWasRunning, RestartCaptureForAudioSettings);
            if (result.State == ActionState.Error) ShowPage(PageVoice);
            ShowActionToast(result);
        };
        triggerMode.SelectedIndexChanged += delegate
        {
            if (updating) return;
            string value = triggerMode.SelectedIndex == 1 ? "hold" : "toggle";
            if (NormalizeProviderKey(config.inputMethod) == "wechat")
            {
                value = "toggle";
                if (value == config.inputMethodTrigger) return;
            }
            else if (value == config.inputMethodTrigger) return;
            VibeMicConfig previousConfig = CloneConfiguration(config);
            bool captureWasRunning = IsCapturing;
            config.inputMethodTrigger = value;
            hotkeyHelp.Text = ProviderHotkeyHelp(config.inputMethod, config.inputMethodTrigger);
            ActionResult result = PersistVoiceConfigurationMutationCore(
                "更改语音触发方式", "语音触发方式已保存", SaveConfig,
                delegate { config = CloneConfiguration(previousConfig); },
                captureWasRunning, RestartCaptureForAudioSettings);
            if (result.State == ActionState.Error) ShowPage(PageVoice);
            ShowActionToast(result);
        };
        processing.SelectedIndexChanged += delegate
        {
            string value = processing.SelectedIndex == 1 ? "transparent" : "speech";
            if (value == config.audioProcessingMode) return;
            VibeMicConfig previousConfig = CloneConfiguration(config);
            bool captureWasRunning = IsCapturing;
            config.audioProcessingMode = value;
            config.autoLevel = value == "speech";
            processingHelp.Text = value == "transparent" ? "仅做格式转换，适合排查原始音频。" : "稳定补偿轻声，孤立尖峰不会压低整段语音。";
            markProfileCustomized();
            ActionResult result = PersistVoiceConfigurationMutationCore(
                "更改声音处理", "声音处理设置已保存", SaveConfig,
                delegate { config = CloneConfiguration(previousConfig); },
                captureWasRunning, RestartCaptureForAudioSettings);
            if (result.State == ActionState.Error) ShowPage(PageVoice);
            ShowActionToast(result);
        };
        autoRoute.CheckedChanged += delegate
        {
            VibeMicConfig previousConfig = CloneConfiguration(config);
            bool captureWasRunning = IsCapturing;
            config.autoRouteVirtualMicrophone = autoRoute.Checked;
            note.Text = VoiceModeNote(config.inputMethod, config.autoRouteVirtualMicrophone);
            markProfileCustomized();
            ActionResult result = PersistVoiceConfigurationMutationCore(
                "更改麦克风路由", "麦克风路由设置已保存", SaveConfig,
                delegate { config = CloneConfiguration(previousConfig); },
                captureWasRunning, RestartCaptureForAudioSettings);
            if (result.State == ActionState.Error) ShowPage(PageVoice);
            ShowActionToast(result);
        };

        content.Controls.Add(card);
        ApplyVisualState(!IsCapturing ? "stopped" : bridgeReady ? "ready" : "connecting");
    }

    private void BuildMappingsPage()
    {
        // The shortcuts canvas grew by 560 px when its cards were laid out to follow the remote itself (the\n        // illustration and the gesture legend now sit underneath the grid).\n        content.AutoScrollMinSize = new Size(1000, 116 + FavoriteAppsCardHeight() + 1626 + 60);
        BridgeHealthSnapshot mappingHealth = ReadKeyboardBridgeHealth();
        bool exactDeviceIsolation = mappingHealth.FilterHealthy;
        AddPageTitle("快捷键", "管理遥控器实体键动作；录音键保持独立");

        var header = NewCard(new Point(34, 100), new Size(960, 204));
        var headerTitle = NewLabel("快捷键 Profile", 14f, FontStyle.Bold, ink);
        headerTitle.Location = new Point(24, 12);
        headerTitle.Size = new Size(220, 28);
        var headerDetail = NewLabel(exactDeviceIsolation ?
            "当前设备级隔离已启用；Profile 仅保存快捷键，不包含任何语音参数" :
            "安全直通下遥控器原按键效果可能同时发生；快捷键 Profile（应用专属的按键方案）不会修改语音链路", 8.6f, FontStyle.Regular, muted);
        headerDetail.Location = new Point(24, 40);
        headerDetail.Size = new Size(590, 22);
        var sourceBadge = NewLabel(exactDeviceIsolation ? "●  精确隔离" : "●  安全直通",
            8.8f, FontStyle.Bold, exactDeviceIsolation ? green : cyan);
        sourceBadge.Location = new Point(804, 18);
        sourceBadge.Size = new Size(126, 34);
        sourceBadge.TextAlign = ContentAlignment.MiddleCenter;
        sourceBadge.BackColor = StatusSurface("ready");
        ApplyRoundedRegion(sourceBadge, 6);

        var profileLabel = NewLabel(config.smartProfilesEnabled ? "默认 Profile" : "当前 Profile",
            8.6f, FontStyle.Bold, muted);
        profileLabel.Location = new Point(24, 79);
        profileLabel.Size = new Size(82, 36);
        profileLabel.TextAlign = ContentAlignment.MiddleLeft;
        var profilePicker = StyledCombo(new Point(108, 78), new Size(208, 38));
        int activeProfileIndex = 0;
        if (config.shortcutProfiles != null)
        {
            for (int i = 0; i < config.shortcutProfiles.Length; i++)
            {
                ShortcutProfileConfig item = config.shortcutProfiles[i];
                profilePicker.Items.Add(new ShortcutProfileChoice(item));
                if (item != null && string.Equals(item.id, config.activeShortcutProfileId,
                    StringComparison.OrdinalIgnoreCase)) activeProfileIndex = i;
            }
        }
        if (profilePicker.Items.Count > 0) profilePicker.SelectedIndex = Math.Min(activeProfileIndex, profilePicker.Items.Count - 1);
        var switchProfile = PrimaryButton(config.smartProfilesEnabled ? "设为默认" : "切换",
            new Point(326, 77), new Size(config.smartProfilesEnabled ? 82 : 72, 40));
        switchProfile.Click += delegate
        {
            ShortcutProfileChoice choice = profilePicker.SelectedItem as ShortcutProfileChoice;
            if (choice != null) SwitchShortcutProfile(choice.Profile.id);
        };
        int profileActionsStart = config.smartProfilesEnabled ? 418 : 408;
        // The five management actions — 新建 / 重命名 / 删除 / 导入 / 导出 — were five equal-weight buttons beside 切换,
        // so the routine action and the destructive one looked identical among seven buttons in one row. They live
        // in a 管理 menu now, with 删除 last behind a separator (it still asks for confirmation). Each item calls the
        // same named method the button called, so nothing about the behaviour changes. Measured before the change:
        // seven buttons in this row; after it, two here and the feature button on the right.
        if (profileMenuStrip != null)
        {
            // The page is rebuilt on every navigation, so the previous menu is disposed with it rather than left
            // behind on each visit.
            profileMenuStrip.Dispose();
            profileMenuStrip = null;
        }
        profileMenuStrip = new ContextMenuStrip();
        profileMenuStrip.Items.Add("新建快捷键 Profile", null, delegate { CreateShortcutProfile(); });
        profileMenuStrip.Items.Add("重命名当前 Profile", null, delegate { RenameActiveShortcutProfile(); });
        profileMenuStrip.Items.Add(new ToolStripSeparator());
        profileMenuStrip.Items.Add("导入配置…", null, delegate { ImportShortcutProfile(); });
        profileMenuStrip.Items.Add("导出当前配置…", null, delegate { ExportActiveShortcutProfile(); });
        profileMenuStrip.Items.Add(new ToolStripSeparator());
        profileMenuStrip.Items.Add("删除当前 Profile…", null, delegate { DeleteActiveShortcutProfile(); });
        var manageProfiles = SecondaryButton("管理", new Point(profileActionsStart, 77), new Size(72, 40));
        manageProfiles.Name = "profileManageButton";
        manageProfiles.Click += delegate
        {
            profileMenuStrip.Show(manageProfiles, new Point(0, manageProfiles.Height));
        };
        var browserRemote = SecondaryButton("浏览器遥控", new Point(830, 77), new Size(100, 40));
        browserRemote.Name = "browserRemoteLiteButton";
        browserRemote.Click += delegate { ShowBrowserRemoteLite(); };
        string effectiveProfile = !string.IsNullOrWhiteSpace(mappingHealth.SmartEffectiveProfileName)
            ? mappingHealth.SmartEffectiveProfileName : (ActiveShortcutProfile(config) == null
                ? "当前方案" : ActiveShortcutProfile(config).name);
        var effectiveBadge = NewLabel(config.smartProfilesEnabled ? "生效 · " + effectiveProfile : "手动模式",
            8.1f, FontStyle.Bold, config.smartProfilesEnabled ? green : violet);
        effectiveBadge.Location = new Point(638, 18);
        effectiveBadge.Size = new Size(152, 34);
        effectiveBadge.TextAlign = ContentAlignment.MiddleCenter;
        effectiveBadge.BackColor = StatusSurface(config.smartProfilesEnabled ? "connected" : "recording");
        ApplyRoundedRegion(effectiveBadge, 6);

        var smartLabel = NewLabel("智能切换", 8.6f, FontStyle.Bold, muted);
