                ShowPage(PageShortcuts);
            };
            rowBand.Controls.Add(icon);
            rowBand.Controls.Add(name);
            rowBand.Controls.Add(input);
            rowBand.Controls.Add(test);
            rowBand.Controls.Add(reset);
            mappings.Controls.Add(rowBand);
