    private void BuildSettingsPage()
    {
        content.AutoScrollMinSize = new Size(1000, 1092);
        AddPageTitle("设置", "让言灵按你的习惯在后台运行");
        var startupCard = NewCard(new Point(34, 100), new Size(580, 360));
        startupCard.Controls.Add(SectionTitle("启动与窗口", "\uE713", new Point(28, 22)));
        Label startupState = null;
        var start = StyledCheck("打开言灵后自动连接遥控器", config.startBridgeOnLaunch, new Point(32, 70));
        bool startChanging = false;
        start.CheckedChanged += delegate
        {
            if (startChanging) return;
            bool previous = config.startBridgeOnLaunch;
            config.startBridgeOnLaunch = start.Checked;
            ActionResult result = ApplySettingsChangeCore("更改自动连接", "自动连接设置已保存", false,
                SaveConfig, null, delegate { config.startBridgeOnLaunch = previous; });
            if (!result.IsSuccess)
            {
                startChanging = true;
                start.Checked = previous;
                startChanging = false;
            }
            ShowActionToast(result);
        };
        var traySetting = StyledCheck("关闭主窗口后继续在系统托盘运行", config.minimizeToTray, new Point(32, 118));
        bool trayChanging = false;
        traySetting.CheckedChanged += delegate
        {
            if (trayChanging) return;
            bool previous = config.minimizeToTray;
            config.minimizeToTray = traySetting.Checked;
            ActionResult result = ApplySettingsChangeCore("更改托盘设置", "托盘运行设置已保存", false,
                SaveConfig, null, delegate { config.minimizeToTray = previous; });
            if (!result.IsSuccess)
            {
                trayChanging = true;
                traySetting.Checked = previous;
                trayChanging = false;
            }
            UpdateStartupSettingsSummary(startupState);
            ShowActionToast(result);
        };
        var startup = StyledCheck("登录 Windows 后自动启动言灵", config.launchAtStartup, new Point(32, 166));
        bool startupChanging = false;
        startup.CheckedChanged += delegate
        {
            if (startupChanging) return;
            bool previous = config.launchAtStartup;
            config.launchAtStartup = startup.Checked;
            ActionResult result = ApplySettingsChangeCore("更改开机启动", "开机启动设置已生效", true,
                SaveConfig,
                delegate { return !uiSmokeMode && ReconcileLaunchAtStartupRegistration(); },
                delegate { config.launchAtStartup = previous; });
            if (!result.IsSuccess)
            {
                startupChanging = true;
                startup.Checked = previous;
                startupChanging = false;
            }
            UpdateStartupSettingsSummary(startupState);
            ShowActionToast(result);
        };
        var themeLabel = NewLabel("界面主题", 9.5f, FontStyle.Bold, ink);
        themeLabel.Location = new Point(32, 218);
        themeLabel.Size = new Size(120, 30);
        var lightTheme = SecondaryButton("白天模式", new Point(154, 212), new Size(106, 38));
        var darkThemeButton = SecondaryButton("夜间模式", new Point(268, 212), new Size(106, 38));
        var systemTheme = SecondaryButton("跟随 Windows", new Point(382, 212), new Size(136, 38));
        bool lightSelected = string.Equals(config.theme, "light", StringComparison.OrdinalIgnoreCase);
        bool darkSelected = string.Equals(config.theme, "dark", StringComparison.OrdinalIgnoreCase);
        bool systemSelected = string.Equals(config.theme, "system", StringComparison.OrdinalIgnoreCase);
        // Three segments of one choice, not three commands.
        //
        // The current choice was drawn as a solid accent button, exactly like the button you would press to *make*
        // it the current choice, so it read as "press me" while it was already selected. Selection is now carried by
        // a tinted fill, an accent border, an accent label and a filled dot; the alternatives stay plain with a
        // hollow dot, which is what a segmented control looks like.
        Action<Button, bool, string> styleThemeSegment = delegate(Button segment, bool selected, string label)
        {
            Color accent = darkTheme ? Color.FromArgb(150, 135, 255) : violet;
            segment.Text = (selected ? "●  " : "○  ") + label;
            segment.BackColor = selected
                ? (darkTheme ? Color.FromArgb(52, 47, 88) : Color.FromArgb(238, 235, 255))
                : surfaceBackground;
            segment.ForeColor = selected ? accent : ink;
            segment.Font = new Font("Microsoft YaHei UI", 9f, selected ? FontStyle.Bold : FontStyle.Regular);
            segment.FlatAppearance.BorderColor = selected ? accent : line;
            segment.FlatAppearance.MouseOverBackColor = selected
                ? (darkTheme ? Color.FromArgb(60, 55, 100) : Color.FromArgb(230, 226, 255))
                : (darkTheme ? Color.FromArgb(47, 49, 57) : Color.FromArgb(240, 243, 250));
            segment.FlatAppearance.MouseDownBackColor = selected
                ? (darkTheme ? Color.FromArgb(68, 62, 112) : Color.FromArgb(220, 215, 252))
                : (darkTheme ? Color.FromArgb(55, 58, 68) : Color.FromArgb(219, 225, 252));
        };
        styleThemeSegment(lightTheme, lightSelected, "白天模式");
        styleThemeSegment(darkThemeButton, darkSelected, "夜间模式");
        styleThemeSegment(systemTheme, systemSelected, "跟随 Windows");
        lightTheme.Click += delegate { ApplyThemePreference("light"); };
        darkThemeButton.Click += delegate { ApplyThemePreference("dark"); };
        systemTheme.Click += delegate { ApplyThemePreference("system"); };
        var startupBand = new Panel();
        startupBand.Location = new Point(30, 282);
        startupBand.Size = new Size(520, 58);
        startupBand.BackColor = surfaceBackground;
        startupState = NewLabel((config.launchAtStartup ? "●  已设置开机启动" : "●  仅在手动打开后运行") + "  ·  " +
            (config.minimizeToTray ? "关闭窗口后保持连接" : "关闭窗口时退出"), 9f, FontStyle.Bold,
            config.launchAtStartup ? green : muted);
        startupState.Location = new Point(16, 17);
        startupState.Size = new Size(486, 26);
        startupBand.Controls.Add(startupState);
        ApplyRoundedRegion(startupBand, 8);
        startupCard.Controls.Add(start);
        startupCard.Controls.Add(traySetting);
        startupCard.Controls.Add(startup);
        startupCard.Controls.Add(themeLabel);
        startupCard.Controls.Add(lightTheme);
        startupCard.Controls.Add(darkThemeButton);
        startupCard.Controls.Add(systemTheme);
        startupCard.Controls.Add(startupBand);

        var feedbackCard = NewCard(new Point(630, 100), new Size(364, 360));
        feedbackCard.Anchor = AnchorStyles.Top | AnchorStyles.Right;
        feedbackCard.Controls.Add(SectionTitle("交互反馈", "\uE8BD", new Point(26, 22)));
        var feedbackSound = StyledCheck("录音结束或失败时播放提示音", config.soundFeedbackEnabled, new Point(28, 72));
        feedbackSound.Size = new Size(308, 40);
        bool feedbackSoundChanging = false;
        feedbackSound.CheckedChanged += delegate
        {
            if (feedbackSoundChanging) return;
            bool previous = config.soundFeedbackEnabled;
            config.soundFeedbackEnabled = feedbackSound.Checked;
            bool saved = SaveConfig();
            ActionResult result = ActionResult.FromConfigurationApply("更改提示音", "本地设置",
                feedbackSound.Checked ? "听写提示音已开启" : "听写提示音已关闭", saved, false, false);
            if (!saved)
            {
                config.soundFeedbackEnabled = previous;
                feedbackSoundChanging = true;
                feedbackSound.Checked = previous;
                feedbackSoundChanging = false;
            }
            ShowActionToast(result);
        };
                // Sized to its text instead of spanning the card: a 284 px tinted bar looked like the card's primary action,
// which it is not.
        var previewStopSound = SecondaryButton("试听结束提示音", new Point(28, 126), new Size(152, 38));
        previewStopSound.Click += delegate
        {
            PlayRecordingCue(false);
            ShowToast("已播放录音结束提示音", "success");
        };
        var feedbackNote = NewLabel("开始录音使用首页光效，不播放声音；结束时播放清晰、短促的完成音。", 8.9f, FontStyle.Regular, muted);
        feedbackNote.Location = new Point(28, 194);
        feedbackNote.Size = new Size(304, 52);
        var feedbackState = NewLabel("●  视觉反馈始终开启", 9f, FontStyle.Bold, violet);
        feedbackState.Location = new Point(28, 258);
        feedbackState.Size = new Size(260, 24);
        feedbackCard.Controls.Add(feedbackSound);
        feedbackCard.Controls.Add(previewStopSound);
        feedbackCard.Controls.Add(feedbackNote);
        feedbackCard.Controls.Add(feedbackState);

        BridgeHealthSnapshot routingHealth = ReadKeyboardBridgeHealth();
        bool exactDeviceIsolation = routingHealth.FilterHealthy;
        var routingCard = NewCard(new Point(34, 476), new Size(960, 172));
        routingCard.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        routingCard.Controls.Add(SectionTitle("按键来源保护", "\uE7BA", new Point(28, 22)));
        // The bold line and the checkbox state follow the actual isolation state, because they used to assert
        // device-level isolation unconditionally while the badge and the note beside them said it was not there:
        // the checkbox was drawn checked and read "只有带 RC003 身份的事件可以执行遥控器动作" even when the note
        // underneath read "言灵不会拦截来源未知的键". A checked box that promises something the same card denies
        // is worse than no statement at all.
        var sourceProtection = StyledCheck(exactDeviceIsolation
            ? "设备级隔离已启用：只有带 RC003 身份的事件会执行遥控器动作"
            : "尚未逐设备隔离：遥控器按键与实体键盘可能同时生效（签名通道为可选增强）",
            exactDeviceIsolation, new Point(32, 62));
        sourceProtection.Size = new Size(620, 40);
        sourceProtection.AutoCheck = false;
        sourceProtection.TabStop = false;
        var sourceProtectionState = NewLabel(exactDeviceIsolation ?
            "●  设备级精确隔离" : "●  Raw Input 安全直通", 9f, FontStyle.Bold,
            exactDeviceIsolation ? green : cyan);
        sourceProtectionState.Location = new Point(660, 68);
        sourceProtectionState.Size = new Size(268, 28);
        var sourceProtectionNote = NewLabel(
            exactDeviceIsolation ?
            "RC003 专属签名通道已就绪：遥控器原按键被设备级拦截，实体键盘保持原行为。" :
            "未安装签名通道时，言灵不拦截来源未知的键：实体键盘保持原样，遥控器自定义键的原始效果可能同时发生。签名通道是可选增强。",
            8.8f, FontStyle.Regular, muted);
        sourceProtectionNote.Location = new Point(34, 112);
        sourceProtectionNote.Size = new Size(890, 34);
        routingCard.Controls.Add(sourceProtection);
        routingCard.Controls.Add(sourceProtectionState);
        routingCard.Controls.Add(sourceProtectionNote);

        var privacyCard = NewCard(new Point(34, 664), new Size(960, 420));
        privacyCard.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        var privacyTitle = SectionTitle("隐私与维护", "\uEA18", new Point(28, 22));
        var privacy = StyledCheck("本地安全模式：默认不保存录音、不上传音频、不读取听写文字", true, new Point(32, 62));
        privacy.AutoCheck = false;
        privacy.TabStop = false;
        privacy.ForeColor = muted;
        var privacyNote = NewLabel("普通日志只记录连接状态与聚合指标，每个日志上限 4 MB。诊断音频每次都要你明确确认。", 8.8f, FontStyle.Regular, muted);
        privacyNote.Location = new Point(34, 104);
        privacyNote.Size = new Size(830, 28);
        var automaticUpdates = StyledCheck("自动检查 GitHub 正式版更新（安装前始终确认）", config.autoCheckUpdates, new Point(32, 132));
        automaticUpdates.Size = new Size(520, 40);
        bool automaticUpdatesChanging = false;
        automaticUpdates.CheckedChanged += delegate
        {
            if (automaticUpdatesChanging) return;
            bool previous = config.autoCheckUpdates;
            config.autoCheckUpdates = automaticUpdates.Checked;
            bool requestedEnabled = automaticUpdates.Checked;
            ActionResult result = ApplySettingsChangeCore("更改更新设置",
                requestedEnabled ? "自动更新检查已开启" : "自动更新检查已关闭", false,
                SaveConfig, null, delegate { config.autoCheckUpdates = previous; });
            if (!result.IsSuccess)
            {
                automaticUpdatesChanging = true;
                automaticUpdates.Checked = previous;
                automaticUpdatesChanging = false;
            }
            ShowActionToast(result);
        };
        var setup = PrimaryButton("重新打开首次设置", new Point(32, 184), new Size(160, 42));
        setup.Click += delegate { ShowSetupWizard(); };
        var export = SecondaryButton("备份配置", new Point(204, 184), new Size(112, 42));
        export.Click += delegate { ExportConfig(); };
        var import = SecondaryButton("导入配置", new Point(328, 184), new Size(112, 42));
        import.Click += delegate { ImportConfig(); };
        var restore = SecondaryButton("恢复上次", new Point(452, 184), new Size(112, 42));
        restore.Click += delegate { RestorePreviousConfig(); };
        // 124 px wide ran 10 px into the product label beside it (measured with
        // scripts/check-ui-geometry.ps1); the label starts further right instead.
        var updates = SecondaryButton("安全检查更新", new Point(576, 184), new Size(108, 42));
        updates.Click += delegate { CheckForUpdates(true); };
        var about = NewLabel(DisplayProductName + " · " + ProductRelease + " · Windows 候选版\r\nRC003 本地语音传输与快捷操作工具 · 尚需完成真机验收", 9.5f, FontStyle.Regular, muted);
        about.Location = new Point(694, 184);
        about.Size = new Size(238, 66);
        var profile = NewLabel("稳定语音档案 v" + StableVoiceProfileVersion + "  ·  参数版本 " + ConfigSchemaVersion, 8.7f, FontStyle.Bold, violet);
        profile.Location = new Point(32, 260);
        profile.Size = new Size(400, 24);
        privacyCard.Controls.Add(privacyTitle);
        privacyCard.Controls.Add(privacy);
        privacyCard.Controls.Add(privacyNote);
        privacyCard.Controls.Add(automaticUpdates);
        privacyCard.Controls.Add(setup);
        privacyCard.Controls.Add(export);
        privacyCard.Controls.Add(import);
        privacyCard.Controls.Add(restore);
        privacyCard.Controls.Add(updates);
        privacyCard.Controls.Add(about);
        privacyCard.Controls.Add(profile);

        // Metadata-only usage statistics: how many sessions ran, how many finished cleanly and the
        // longest gap between two of them, all derived from the local receipt log. No text is read and
        // nothing is stored, which is exactly what the caption under the numbers promises.
        UsageStats usageStats = BuildUsageStats();
        var usageTitle = NewLabel("使用统计（仅元数据）", 9.4f, FontStyle.Bold, ink);
        usageTitle.Location = new Point(32, 296);
        usageTitle.Size = new Size(420, 26);
        var usageLine = NewLabel(UsageStatsLine(usageStats), 9.6f, FontStyle.Bold, violet);
        usageLine.Location = new Point(32, 326);
        usageLine.Size = new Size(890, 26);
        var usageNote = NewLabel("只统计当前日志窗口内有结束回执的会话（日志限长，旧记录随滚动丢弃）；不含录音、转写文字、窗口标题或设备地址。", 8.6f, FontStyle.Regular, muted);
        usageNote.Location = new Point(32, 354);
        usageNote.Size = new Size(890, 42);
        privacyCard.Controls.Add(usageTitle);
        privacyCard.Controls.Add(usageLine);
        privacyCard.Controls.Add(usageNote);

        // A glossary, because the interface uses English product terms — Profile, Smart Profiles, Browser Remote
        // Lite, Raw Input, Live HUD, Context Deck — and until now none of them was explained anywhere in the
        // application. The first occurrence of each is glossed in place as well; this is the one place a user can
        // look them all up without hunting through the pages.
        var glossaryCard = NewCard(new Point(34, 1100), new Size(960, 300));
        glossaryCard.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        glossaryCard.Controls.Add(SectionTitle("术语表", "\uE8D2", new Point(28, 22)));
        string[,] glossary =
        {
            { "快捷键 Profile", "某个应用专属的一套按键动作。绑定后，切到该应用会自动使用它。" },
            { "Smart Profiles", "按当前应用自动切换键位方案；不修改录音与转写链路。" },
            { "Browser Remote Lite", "用遥控器按键操作浏览器的轻量配置：先看差异，再应用或一键撤销。" },
            { "Raw Input", "Windows 直接投递的原始键盘事件。「安全直通」表示尚未做逐设备隔离。" },
            { "Live HUD", "不抢焦点的悬浮状态窗；主窗口不在前台时仍能看到录音状态。" },
            { "Context Deck", "遥控器、Profile、目标与最近一次动作的详细面板，从托盘菜单打开。" }
        };
        for (int row = 0; row < glossary.GetLength(0); row++)
        {
            var term = NewLabel(glossary[row, 0], 9f, FontStyle.Bold, ink);
            term.Location = new Point(32, 64 + row * 34);
            term.Size = new Size(190, 26);
            var meaning = NewLabel(glossary[row, 1], 9f, FontStyle.Regular, muted);
            meaning.Location = new Point(232, 64 + row * 34);
            meaning.Size = new Size(690, 26);
            meaning.AutoEllipsis = true;
            glossaryCard.Controls.Add(term);
            glossaryCard.Controls.Add(meaning);
        }
        content.Controls.Add(glossaryCard);
        content.AutoScrollMinSize = new Size(1000, 1610);

        // Interface scale. Some users cannot read a 9 pt label on a dense screen, and the display's own scaling is
        // not always something they can change. The choice applies on the next start: the window and its layout are
        // sized when they load, and the note under the segments says so rather than leaving a user to wonder why
        // nothing moved.
        var scaleCard = NewCard(new Point(34, 1420), new Size(960, 150));
        scaleCard.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        scaleCard.Controls.Add(SectionTitle("界面缩放", "\uE7F8", new Point(28, 22)));
        int currentScale = config.uiScalePercent <= 0 ? 100 : config.uiScalePercent;
        Button[] scaleSegments = new Button[3];
        int[] scaleValues = { 100, 110, 125 };
        for (int i = 0; i < scaleValues.Length; i++)
        {
            int value = scaleValues[i];
            bool selected = value == currentScale;
            var segment = SecondaryButton((selected ? "●  " : "○  ") + value + "%",
                new Point(32 + i * 118, 64), new Size(106, 40));
            segment.Name = "uiScaleSegment" + value;
            Color segmentAccent = darkTheme ? Color.FromArgb(150, 135, 255) : violet;
            segment.BackColor = selected
                ? (darkTheme ? Color.FromArgb(52, 47, 88) : Color.FromArgb(238, 235, 255))
                : surfaceBackground;
            segment.ForeColor = selected ? segmentAccent : ink;
            segment.Font = new Font("Microsoft YaHei UI", 9f, selected ? FontStyle.Bold : FontStyle.Regular);
            segment.FlatAppearance.BorderColor = selected ? segmentAccent : line;
            segment.Click += delegate
            {
                if (config.uiScalePercent == value) return;
                config.uiScalePercent = value;
                bool saved = SaveConfig();
                HostLog("UI SCALE set=" + value + " saved=" + saved);
                ShowPage(currentPageIndex);
                ShowToast(saved ? "界面缩放已设为 " + value + "%，重启言灵后生效"
                    : "界面缩放保存失败：请检查数据目录", saved ? "info" : "error");
            };
            scaleSegments[i] = segment;
            scaleCard.Controls.Add(segment);
        }
        var scaleNote = NewLabel("在 Windows 显示缩放之上再放大整个界面；改动在重启言灵后生效。",
            8.8f, FontStyle.Regular, muted);
        scaleNote.Location = new Point(400, 72);
        scaleNote.Size = new Size(530, 24);
        scaleNote.TextAlign = ContentAlignment.MiddleRight;
        scaleCard.Controls.Add(scaleNote);
        content.Controls.Add(scaleCard);

        content.Controls.Add(startupCard);
        content.Controls.Add(feedbackCard);
        content.Controls.Add(routingCard);
        content.Controls.Add(privacyCard);
    }

