    // A vertical stack of labels whose spacing follows the height the current display scaling really
    // renders, instead of an absolute y offset tuned at 100%. A 27 pt line is about 47 px tall at 100%
    // and about 59 px at 125%, so every page's title ran into the line beneath it (measured with
    // scripts/check-ui-geometry.ps1 at 125%: all six pages, plus the sidebar mark). Reading a label's
    // Bottom before it is parented does not help either — it returns the framework's default height of
    // 23 px while the label renders 42 px (measured), which is why an earlier attempt at this made the
    // overlap worse. A TopDown flow panel asks each child for its preferred size at render time, so the
    // stack is correct at every scaling.
    private static FlowLayoutPanel NewLabelStack(Point location, int gap, params Label[] labels)
    {
        var stack = new FlowLayoutPanel();
        stack.Location = location;
        stack.FlowDirection = FlowDirection.TopDown;
        stack.WrapContents = false;
        stack.AutoSize = true;
        stack.AutoSizeMode = AutoSizeMode.GrowAndShrink;
        stack.BackColor = Color.Transparent;
        stack.Margin = new Padding(0);
        stack.Padding = new Padding(0);
        stack.TabStop = false;
        for (int index = 0; index < labels.Length; index++)
        {
            Label label = labels[index];
            if (label == null) continue;
            // AutoSize is what makes the container measure the text at the current scaling. Without it
            // a label keeps WinForms' default 100x23 box: measured at 125%, every stacked label came
            // back as 100x23 and its text was cut off, which is exactly the "squashed interface" shape
            // a user reports.
            label.AutoSize = true;
            label.Margin = new Padding(label.Margin.Left, 0, 0, index == labels.Length - 1 ? 0 : gap);
            stack.Controls.Add(label);
        }
        return stack;
    }

    private Bitmap CreateNavigationIcon(string icon, Color color, bool active)
    {
        // Drawn in 34x24 design units on a surface scaled by the display ratio: a fixed bitmap stayed
        // 34x24 while its button doubled, so the icons looked progressively smaller as the scaling grew.
        float scale = DesignScale();
        var bitmap = new Bitmap(Math.Max(1, (int)Math.Round(34 * scale)),
            Math.Max(1, (int)Math.Round(24 * scale)));
        using (Graphics graphics = Graphics.FromImage(bitmap))
        using (var pen = new Pen(color, active ? 2.05f : 1.75f))
        using (var soft = new SolidBrush(Color.FromArgb(active ? 42 : 18, color)))
        using (var solid = new SolidBrush(color))
        {
            graphics.Clear(Color.Transparent);
            graphics.SmoothingMode = SmoothingMode.AntiAlias;
            graphics.PixelOffsetMode = PixelOffsetMode.HighQuality;
            graphics.ScaleTransform(scale, scale);
            pen.StartCap = LineCap.Round;
            pen.EndCap = LineCap.Round;
            pen.LineJoin = LineJoin.Round;

            if (icon == "overview")
            {
                graphics.FillRoundedRectangle(soft, new Rectangle(2, 3, 8, 8), 2);
                graphics.DrawRoundedRectangle(pen, new Rectangle(2, 3, 8, 8), 2);
                graphics.DrawRoundedRectangle(pen, new Rectangle(13, 3, 8, 8), 2);
                graphics.DrawRoundedRectangle(pen, new Rectangle(2, 14, 8, 7), 2);
                graphics.DrawRoundedRectangle(pen, new Rectangle(13, 14, 8, 7), 2);
            }
            else if (icon == "projects")
            {
                graphics.FillRoundedRectangle(soft, new Rectangle(2, 6, 20, 14), 3);
                graphics.DrawRoundedRectangle(pen, new Rectangle(2, 6, 20, 14), 3);
                graphics.DrawLines(pen, new PointF[] {
                    new PointF(4, 6), new PointF(7, 3), new PointF(13, 3), new PointF(16, 6)
                });
                graphics.DrawLine(pen, 6, 11, 18, 11);
            }
            else if (icon == "voice")
            {
                graphics.FillRoundedRectangle(soft, new Rectangle(6, 2, 8, 13), 4);
                graphics.DrawRoundedRectangle(pen, new Rectangle(6, 2, 8, 13), 4);
                graphics.DrawArc(pen, new Rectangle(3, 7, 14, 12), 0, 180);
                graphics.DrawLine(pen, 10, 19, 10, 22);
                graphics.DrawLine(pen, 7, 22, 13, 22);
                graphics.DrawArc(pen, new Rectangle(16, 6, 6, 9), -70, 140);
            }
            else if (icon == "shortcuts")
            {
                graphics.FillRoundedRectangle(soft, new Rectangle(1, 4, 21, 16), 3);
                graphics.DrawRoundedRectangle(pen, new Rectangle(1, 4, 21, 16), 3);
                for (int i = 0; i < 3; i++) graphics.FillRoundedRectangle(solid, new Rectangle(5 + i * 5, 8, 3, 3), 1);
                graphics.DrawLine(pen, 5, 16, 18, 16);
            }
            else if (icon == "diagnostics")
            {
                using (var path = new GraphicsPath())
                {
                    path.AddLines(new PointF[] {
                        new PointF(11.5f, 2), new PointF(20.5f, 5.5f), new PointF(19.5f, 14),
                        new PointF(16.5f, 19), new PointF(11.5f, 22), new PointF(6.5f, 19),
                        new PointF(3.5f, 14), new PointF(2.5f, 5.5f)
                    });
                    path.CloseFigure();
                    graphics.FillPath(soft, path);
                    graphics.DrawPath(pen, path);
                }
                graphics.DrawLines(pen, new PointF[] { new PointF(6.5f, 12), new PointF(10, 15.5f), new PointF(16.8f, 8.5f) });
            }
            else
            {
                int[] knobX = { 8, 16, 11 };
                for (int i = 0; i < 3; i++)
                {
                    int y = 5 + i * 7;
                    graphics.DrawLine(pen, 2, y, 21, y);
                    graphics.FillEllipse(soft, knobX[i] - 3, y - 3, 6, 6);
                    graphics.FillEllipse(solid, knobX[i] - 1, y - 1, 3, 3);
                }
            }
        }
        return bitmap;
    }

    private static Bitmap CreateGlyphBitmap(string glyph, Color color, int width, int height, float fontSize)
    {
        var bitmap = new Bitmap(width, height);
        using (Graphics graphics = Graphics.FromImage(bitmap))
        using (var font = UiFonts.Icon(fontSize, FontStyle.Regular))
        using (var brush = new SolidBrush(color))
        {
            graphics.Clear(Color.Transparent);
            graphics.SmoothingMode = SmoothingMode.AntiAlias;
            graphics.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
            SizeF size = graphics.MeasureString(glyph ?? "", font);
            graphics.DrawString(glyph ?? "", font, brush, (width - size.Width) / 2f, (height - size.Height) / 2f);
        }
        return bitmap;
    }

