                            pageContent.Controls.Add(title);
                            pageContent.Controls.Add(detail);
                        }
                        var device = NewLabel("适用：Windows 10 / 11 · 小米蓝牙语音遥控器 Pro 2 / RC003", 9f, FontStyle.Bold, violet);
                        device.Location = new Point(8, 458);
                        device.Size = new Size(650, 30);
                        pageContent.Controls.Add(device);
                        // Stated here rather than only on the home page: while the device-level filter is not
                        // healthy the record key can reach the foreground application, and a first-run user
                        // should not have to discover that from a badge on a later screen. Shown only when that
                        // is actually the case; measured afterwards, this step still reports no overlapping or
                        // clipped controls.
                        if (!ReadKeyboardBridgeHealth().FilterHealthy)
                        {
                            var keyIsolation = NewLabel(
                                "!  录音键当前为安全直通：前台应用可能同时收到录音键；设备级精确隔离仍在开发中。",
                                8.6f, FontStyle.Bold, amber);
                            keyIsolation.Name = "onboardingKeyIsolationNotice";
                            keyIsolation.Location = new Point(8, 494);
                            keyIsolation.Size = new Size(690, 28);
                            pageContent.Controls.Add(keyIsolation);
                        }
                    }
                    else if (currentStep == 1)
                    {
                        BridgeHealthSnapshot snapshot = ReadKeyboardBridgeHealth();
                        bool remoteReady = bridgeReady || snapshot.RawInputDevicePresent;
                        bool keyObserved = HasFreshOnboardingDirectionEvidence(snapshot, keyBaselineUtc);
                        var status = NewLabel(remoteReady ? "●  RC003 已连接" : "●  尚未识别 RC003", 13f, FontStyle.Bold,
                            remoteReady ? green : amber);
                        status.Location = new Point(8, 112);
                        status.Size = new Size(600, 36);
                        var keyState = NewLabel(keyObserved ? "✓ 已收到刚才的方向键" : "现在按一次遥控器方向键，然后点击重新检测",
                            9.4f, FontStyle.Bold, keyObserved ? green : cyan);
                        keyState.Location = new Point(8, 158);
                        keyState.Size = new Size(650, 34);
                        var detail = NewLabel(remoteReady ?
                            "按键桥接会在遥控器休眠、蓝牙晚启动或电脑唤醒后自动恢复。" :
                            "打开 Windows 蓝牙设置，添加 RC003；完成后按方向键唤醒遥控器。", 9f, FontStyle.Regular, muted);
                        detail.Location = new Point(8, 204);
