                        var install = PrimaryButton(inputReady && outputReady ? "打开声音设置" : "安装官方 VB-CABLE", new Point(8, 374), new Size(190, 42));
                        install.Click += delegate
                        {
                            if (inputReady && outputReady) OpenUri("ms-settings:sound");
