                            inputReady && outputReady ? green : amber);
                        required.Location = new Point(6, 94);
                        required.Size = new Size(420, 24);
                        var route = NewCard(new Point(4, 124), new Size(602, 224));
                        var routeTitle = NewLabel(triggerOnlyStep ?
